// Field names used below:
// * `+0x10C` horizontal speed (`ACTOR_SPEED`);
// * `+0x110` target/vertical speed (`ACTOR_SPEED_TARGET`);
// * `+0x11C` animation rate (`ACTOR_ANIM_RATE`);
// * `+0x111C` player state index (`ACTOR_STATE`);
// * `+0x1090` stage/terrain index (`ACTOR_STAGE`);
// * `+0x10D4` / `+0x10D8` flag words (`ACTOR_FLAGS`, `ACTOR_FLAGS2`);
// * `+0x1014` event-flag bit array (`ACTOR_EVENT_FLAGS`).
// ===========================================================================

// ---------------------------------------------------------------------------
// Wave-4 field offsets and tables.
// ---------------------------------------------------------------------------

/// Class vtable pointer, loaded and indexed by the `call_actor_slot*` helpers.
const ACTOR_CLASS_VTABLE: usize = 0x060;

/// `f32` horizontal speed.
const ACTOR_SPEED: usize = 0x10C;

/// `f32` target speed / vertical speed.
const ACTOR_SPEED_TARGET: usize = 0x110;

/// `f32` animation rate.
const ACTOR_ANIM_RATE: usize = 0x11C;

/// `i32` player state index.
const ACTOR_STATE: usize = 0x111C;

/// `i32` stage/terrain index (`3` is water in several branches).
const ACTOR_STAGE: usize = 0x1090;

/// First `u32` flag word.
const ACTOR_FLAGS: usize = 0x10D4;

/// Second `u32` flag word.
const ACTOR_FLAGS2: usize = 0x10D8;

/// Base of the event-flag bit array; bit `n` lives in word `n / 32`.
const ACTOR_EVENT_FLAGS: usize = 0x1014;

/// Actor sub-object pointer used for scene/terrain queries.
const ACTOR_SUB: usize = 0x0DE8;

/// `f32[3]` rate table at `0x802EEAC0` (`1.1, 0.9, 1.0`), indexed by the
/// animation-controller column returned by `0x80070820`. Verified in
/// `main.elf`.
const ANIM_RATE_TABLE_B: usize = 0x802E_EAC0;

/// `f32[3]` rate table at `0x802EEAD8` (`0.5, 0.8, 1.0`), indexed by the
/// low byte of the actor's `+0xE8` virtual slot.
const ANIM_RATE_TABLE_C: usize = 0x802E_EAD8;

/// `f32[3]` rate table at `0x802EEAE4` (`0.5, 0.8, 1.0`). Same use as
/// [`ANIM_RATE_TABLE_C`] but in the quicksand path.
const ANIM_RATE_TABLE_D: usize = 0x802E_EAE4;

/// Six 16-byte pose blocks at `0x802F55B8`, selected by the pose state and the
/// model variant. Each block is four `f32` values copied to the caller.
const POSE_BLOCK_TABLE: usize = 0x802F_55B8;

/// `0.05f` at `0x8042B904` (`r2 - 0x777C`), written to `+0x11C` when event
/// flag `0x31` is clear in [`fn_8004bac0`].
const ANIM_RATE_SLOW: f32 = 0.05;

/// `0.09f` at `0x8042B908` (`r2 - 0x7778`), written when flag `0x31` is set.
const ANIM_RATE_FAST: f32 = 0.09;

/// `3.0f` at `0x8042B8A0` (`r2 - 0x77E0`), the multiplier applied while event
/// flag `0x89` is set.
const ANIM_RATE_BOOST: f32 = 3.0;

/// `0.375f` at `0x8042B914` (`r2 - 0x776C`), a damping factor in
/// [`fn_8004c1e0`].
const ANIM_RATE_DAMP: f32 = 0.375;

/// `0.25f` at `0x8042B918` (`r2 - 0x7768`), the low-speed damping factor.
const ANIM_RATE_DAMP_LOW: f32 = 0.25;

/// `0.004f` at `0x8042B910` (`r2 - 0x7770`), the near-stop rate.
const ANIM_RATE_STOP: f32 = f32::from_bits(0x3B83_126F);

/// `1.3f` at `0x8042BA10` (`r2 - 0x7670`), the minimum speed for the slip
/// predicate in [`fn_800578d0`].
const SLIP_MIN_SPEED: f32 = f32::from_bits(0x3FA6_6666);

/// `0.1f` at `0x8042B8D0` (`r2 - 0x77B0`), the lower knee of the speed ramp in
/// [`fn_8004c700`].
const SPEED_RAMP_KNEE: f32 = f32::from_bits(0x3DCC_CCCD);

/// `0.9f` at `0x8042B91C` (`r2 - 0x7764`), the ramp span.
const SPEED_RAMP_SPAN: f32 = f32::from_bits(0x3F66_6666);

/// `1.11111f` at `0x8042B920` (`r2 - 0x7760`), the final ramp scale.
const SPEED_RAMP_SCALE: f32 = f32::from_bits(0x3F8E_38DA);

/// `3700.0f` at `0x8042B934` (`r2 - 0x774C`), used as the Z position when the
/// actor's `+0x1035` byte is `1` in [`fn_8004cc10`].
const LAND_SMOKE_Z: f32 = 3700.0;

/// `0.6f` at `0x8042B92C` (`r2 - 0x7754`), a landing smoke scale.
const LAND_SMOKE_SCALE_WATER: f32 = f32::from_bits(0x3F19_999A);

/// `0.8f` at `0x8042B930` (`r2 - 0x7750`), a landing smoke scale.
const LAND_SMOKE_SCALE_GROUND: f32 = f32::from_bits(0x3F4C_CCCD);

/// Pointer table at `0x80307F18`, indexed by `state * 2 + (stage != 3)`;
/// entries are `Wm_mr_slipsmoke*` names.
const SLIP_SMOKE_TABLE: usize = 0x8030_7F18;

/// Pointer table at `0x80308188`, indexed by `state * 2 + terrain byte`; the
/// entries name `Wm_mr_turn_*` effects.
const TURN_EFFECT_TABLE: usize = 0x8030_8188;

/// Byte sound-id table in BSS at `0x803546F8`, lazily filled by
/// [`fn_8004d040`] and indexed by the player state.
const TURN_SOUND_TABLE: usize = 0x8035_46F8;

/// BSS byte that records whether [`TURN_SOUND_TABLE`] was filled.
/// `r13 - 0x59F6` with `r13 = 0x8042F680`.
const TURN_SOUND_TABLE_READY: usize = 0x8042_9C8A;

/// Pointer table at `0x80307D8C`, indexed by `state * 3 + variant`; entries are
/// `Wm_mr_landsmoke*` / `Wm_mr_watersplash` names.
const LAND_SMOKE_TABLE: usize = 0x8030_7D8C;

/// Pointer table at `0x80308248`, indexed by the player state; entries name the
/// `Wm_mr_foot_*` effects.
const FOOT_EFFECT_TABLE: usize = 0x8030_8248;

/// Pointer table at `0x803082B4`: `Wm_mr_sanddive`, `..._m`, `..._s`.
const SAND_DIVE_TABLE: usize = 0x8030_82B4;

/// `f32` table in BSS at `0x80370DA8`; indexed by a terrain byte from the
/// actor sub-object. The original reads it without a bounds check.
const TERRAIN_SCALE_TABLE: usize = 0x8037_0DA8;

/// Descriptor word at `0x803089B0`, passed as the first word of the small
/// parameter block used by the actor's `+0x294` virtual slot.
const ACTOR_DESC_803089B0: u32 = 0x8030_89B0;

/// Global object at `0x8035429C`, passed as the second argument of the actor's
/// `+0x294` virtual slot. It lives in BSS and is populated at runtime.
const ACTOR_SLOT_8035429C: u32 = 0x8035_429C;

// ---------------------------------------------------------------------------
// Wave-5 field offsets, BSS tables and constants.
//
// `r2 = 0x80433080` and `r13 = 0x8042F680`; every `r2 - k` / `r13 - k`
// below was resolved with those bases and then read from `main.elf` or from
// the BSS segment map.
// ---------------------------------------------------------------------------

/// `f32` table at `0x802F5580`: seven animation rates for variant `0` followed
/// by seven for the non-zero model variant. Used by [`fn_8004c310`].
const ALT_ANIM_RATE_TABLE: usize = 0x802F_5580;

/// BSS `u32[13]` at `0x803546C4`, lazily filled by [`fn_8004ca60`] with sound
