const STATE_SOUND_TABLE: usize = 0x8035_46C4;

/// BSS byte at `0x80429C89` (`r13 - 0x59F7`): [`STATE_SOUND_TABLE`] is ready.
const STATE_SOUND_READY: usize = 0x8042_9C89;

/// BSS `u32[13]` at `0x8035472C`, lazily filled by [`fn_8004d5c0`] with effect
/// ids indexed by the player state.
const STATE_EFFECT_TABLE: usize = 0x8035_472C;

/// BSS byte at `0x80429C8B` (`r13 - 0x59F5`): [`STATE_EFFECT_TABLE`] is ready.
const STATE_EFFECT_READY: usize = 0x8042_9C8B;

/// Global `i32` at `0x8042A204` (`r13 - 0x547C`). Value `2` suppresses the
/// state-effect call in [`fn_8004d5c0`] (likely the pause/menu mode; the name
/// is inferred).
const GLOBAL_MODE_8042A204: usize = 0x8042_A204;

/// Global object at `0x8042A008` (`r13 - 0x5678`), the owner table passed to
