const GROUND_PROBE_80429D50: usize = 0x8042_9D50;

/// Interface name `&DAT_8035455C`, queried by [`fn_8004a2c0`].
const IFACE_NAME_8035455C: u32 = 0x8035_455C;

/// Interface name `&DAT_8035431C`, used when the linked actor is absent in
/// [`fn_8004a920`].
const IFACE_NAME_8035431C: u32 = 0x8035_431C;

/// First `f32` of the effect position pair at `0x80370E20` (BSS, runtime).
const EFFECT_POS_A_80370E20: usize = 0x8037_0E20;

/// Second `f32` of the effect position pair at `0x80370E24` (BSS, runtime).
const EFFECT_POS_B_80370E24: usize = 0x8037_0E24;

/// `f32` pair at `0x80371444` / `0x80371448`, passed to the interface effect in
