const EFFECT_A_80371444: usize = 0x8037_1444;

/// See [`EFFECT_A_80371444`].
const EFFECT_B_80371448: usize = 0x8037_1448;

/// `f32` pair at `0x803714B0` / `0x803714B4`, passed to the interface effect in
