const STOP_IMPULSE_Y: f32 = -1800.0;

// ---------------------------------------------------------------------------
// Wave-4 vtable helpers.
// ---------------------------------------------------------------------------

/// Calls `vtable[slot]` from the actor vtable with `player` as the only
/// argument and returns its result.
///
/// # Safety
/// `player + 0x60` must hold a valid vtable pointer and `slot` must name a
/// one-argument method.
unsafe fn call_actor_slot1(player: usize, slot: usize) -> u32 {
    let vtable = platform::read_u32(player + ACTOR_CLASS_VTABLE) as usize;
    let method = platform::read_u32(vtable + slot) as usize;
    platform::call1(method, player as u32)
}

/// Calls `vtable[slot]` from the actor vtable with three arguments
/// (`player`, `arg1`, `arg2`).
///
/// # Safety
/// `player + 0x60` must hold a valid vtable pointer and `slot` must name a
/// three-argument method.
unsafe fn call_actor_slot3(player: usize, slot: usize, arg1: u32, arg2: u32) -> u32 {
    let vtable = platform::read_u32(player + ACTOR_CLASS_VTABLE) as usize;
    let method = platform::read_u32(vtable + slot) as usize;
    platform::call3(method, player as u32, arg1, arg2)
}

/// Address of the event-flag word that holds `flag`.
///
/// The original computes `(flag >> 5) + (flag < 0 && flag & 31 != 0)` and adds
/// it as a word index to `+0x1014`; that is C's round-toward-zero division by
/// 32 for negative values. All call sites use non-negative flag ids, but the
/// helper keeps the signed form.
///
/// # Safety
/// `flag` is only arithmetic; the caller must ensure the resulting word is
/// inside the actor object.
unsafe fn event_flag_word(player: usize, flag: u32) -> usize {
    let signed = flag as i32;
    let mut word = signed >> 5;
    if signed < 0 && (flag & 0x1F) != 0 {
        word += 1;
    }
    player + ACTOR_EVENT_FLAGS + (word as usize) * 4
}

/// Calls `vtable[slot]` on the actor with one `f32` argument in `f1`.
///
/// # Safety
/// `player + 0x60` must hold a valid vtable pointer and `slot` must name a
/// method whose second argument is `f32`.
unsafe fn call_actor_slot_f32(player: usize, slot: usize, value: f32) {
    let vtable = platform::read_u32(player + ACTOR_CLASS_VTABLE) as usize;
    let method = platform::read_u32(vtable + slot) as usize;
    let function: extern "C" fn(u32, f32) -> u32 = core::mem::transmute(method);
    let _ = function(player as u32, value);
}

/// Calls `vtable[slot]` on the actor and returns an `f32` result.
///
/// # Safety
/// `player + 0x60` must hold a valid vtable pointer and `slot` must name a
/// method that returns `f32` in `f1`.
unsafe fn call_actor_slot_f32_ret(player: usize, slot: usize) -> f32 {
    let vtable = platform::read_u32(player + ACTOR_CLASS_VTABLE) as usize;
    let method = platform::read_u32(vtable + slot) as usize;
    let function: extern "C" fn(u32) -> f32 = core::mem::transmute(method);
    function(player as u32)
}

/// Calls `vtable[slot]` on an interface object with `(f32, f32, f32, object,
/// u32)` and returns the integer result.
///
/// The three floats occupy `f1..f3`; the object and the id occupy `r3`/`r4`.
/// This is the shape of the `+0x5C` methods called by the effect helpers.
///
/// # Safety
/// `object` must start with a vtable pointer and `slot` must name this exact
/// five-argument method.
unsafe fn call_interface_slot_f32x3(
    object: usize,
    slot: usize,
    a: f32,
    b: f32,
    c: f32,
    id: u32,
) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let method = platform::read_u32(vtable + slot) as usize;
    let function: extern "C" fn(f32, f32, f32, u32, u32) -> u32 =
        core::mem::transmute(method);
    function(a, b, c, object as u32, id)
}

/// Calls `0x8015F470`, a "move a float toward a target" helper with signature
/// `(float *value, f32 target, f32 step)`.
///
/// # Safety
/// `value` must point to a writable `f32`, and `step` must be meaningful to
/// the original helper (zero means "no limit" in its other callers).
unsafe fn call_move_f32(value: usize, target: f32, step: f32) {
    let function: extern "C" fn(u32, f32, f32) -> u32 =
        core::mem::transmute(0x8015_F470usize);
    let _ = function(value as u32, target, step);
}

// ---------------------------------------------------------------------------
// 0x8004BAC0 - horizontal-speed dispatcher
// ---------------------------------------------------------------------------

/// Chooses the horizontal animation/speed branch from the actor's fast-animation
/// predicate, movement state and event flags.
///
/// The function is the shared dispatcher used by the player state machine:
/// * when [`fn_8004b1a0`] is clear, it either writes a small `0.05`/`0.09`
///   animation rate and calls [`fn_8004c1e0`], or hands off to `0x8004BC80`;
/// * otherwise it takes the signed direction from the speed sign, reads
///   [`fn_8004b580`], refines the rate through `0x80070820` and the
///   `0x802EEAC0` table, and finally consults the movement entry from
///   `0x8005E7A0` to choose [`fn_8004b520`], the model's `+0x18` float, or the
///   normal rate.
///
/// # Original
/// - Ghidra: `FUN_8004BAC0` at `0x8004BAC0` (440 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004bac0_FUN_8004bac0.c`
///
/// # Arguments
/// - `player`: gameplay player object.
/// - `param_2`: `1` selects the short animation-rate branch, `0` the full
///   movement-state branch. The value is also forwarded to [`fn_8004c1e0`].
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x11C` (animation rate) many times; calls the movement query
/// `0x8005E7A0`, the animation controller `0x80070820`, the model getter
/// `0x80057650`, and the event-flag test `0x80056CF0`.
///
/// # Safety
/// `player + 0xEA4` must be a live movement-state object, and `player + 0x1EC`
/// a live animation controller.
///
/// # Confidence
/// medium - the control flow and constants were verified against `main.elf`;
/// the individual state meanings are inferred from their use.
pub unsafe fn fn_8004bac0(player: usize, param_2: u32) {
    if fn_8004b1a0(player) == 0 {
        if param_2 == 1 {
            // observed 0x8004BB24: event flag 0x31 picks 0.09, clear picks 0.05.
            let rate = if platform::call2(0x8005_6CF0, player as u32, 0x31) == 0 {
                ANIM_RATE_SLOW
            } else {
                ANIM_RATE_FAST
            };
            platform::write_f32(player + ACTOR_ANIM_RATE, rate);
            fn_8004c1e0(player, 1);
        } else {
            // observed: 0x8004BC80 is the full animation-rate selection path;
            // it reads the same pose state and is called only here.
            fn_8004bc80(player);
        }
        return;
    }

    // observed 0x8004BAF8: `fcmpu` / `bge` skips the assignment, so the byte
    // is 1 only when `speed < 0.0`; it is reused by the 0x8004B520 lookup.
    let mut entry = [0u32; 3];
    entry[0] = (platform::read_f32(player + ACTOR_SPEED) < 0.0) as u32;
    platform::write_f32(
        player + ACTOR_ANIM_RATE,
        fn_8004b580(player, entry[0]),
    );

    if platform::call2(
        0x8005_E7A0,
        (player + ACTOR_MOVE_STATE) as u32,
        entry.as_mut_ptr() as u32,
    ) != 0
    {
        // observed 0x8004BB2C..0x8004BB50: the animation controller returns a
        // column that indexes the 1.1/0.9/1.0 table.
        let column = platform::call2(
            0x8007_0820,
            (player + ACTOR_ANIM) as u32,
            entry[0] & 0xFF,
        );
        let factor = platform::read_f32(ANIM_RATE_TABLE_B + (column as usize) * 4);
        platform::write_f32(
            player + ACTOR_ANIM_RATE,
            platform::read_f32(player + ACTOR_ANIM_RATE) * factor,
        );
    }

    if param_2 == 0 {
        if platform::call2(
            0x8005_E7A0,
            (player + ACTOR_MOVE_STATE) as u32,
            entry.as_mut_ptr() as u32,
        ) == 0
        {
            platform::write_f32(
                player + ACTOR_ANIM_RATE,
                fn_8004b520(player, entry[0] & 0xFF),
            );
            if platform::call2(0x8005_6CF0, player as u32, 0x89) != 0 {
                platform::write_f32(
                    player + ACTOR_ANIM_RATE,
                    ANIM_RATE_BOOST * platform::read_f32(player + ACTOR_ANIM_RATE),
                );
            }
        } else {
            // observed 0x8004BBB0: terrain byte at +0x348 indexes the
            // 16-entry direction/scale table at 0x8042B840.
            let terrain = platform::read_u8(player + 0x348) as usize;
            let scaled = platform::read_f32(player + ACTOR_SPEED)
                * platform::read_f32(ANIM_DIR_SCALE + terrain * 4);
            if scaled < 0.0 {
                let model = platform::call1(0x8005_7650, player as u32) as usize;
                platform::write_f32(
                    player + ACTOR_ANIM_RATE,
                    platform::read_f32(model + 0x18),
                );
                if platform::call2(0x8005_6CF0, player as u32, 0x89) == 0 {
                    return;
                }
                platform::write_f32(
                    player + ACTOR_ANIM_RATE,
                    ANIM_RATE_BOOST * platform::read_f32(player + ACTOR_ANIM_RATE),
                );
                return;
            }
        }
    }

    fn_8004c1e0(player, param_2);
}

// ---------------------------------------------------------------------------
// 0x8004C0D0 - copy the pose block selected by the model variant
// ---------------------------------------------------------------------------

/// Copies one of six four-float pose blocks into caller storage.
///
/// The model variant comes from the actor's vtable `+0x3D4`; a non-zero value
/// adds `0x10` to the block address. The pose state from [`fn_8004bf00`] then
/// selects the block base (`+0x00`, `+0x20`, `+0x40`). States other than
/// `0`, `1` and `2` copy nothing.
///
/// # Original
/// - Ghidra: `FUN_8004C0D0` at `0x8004C0D0` (264 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004c0d0_FUN_8004c0d0.c`
///
/// # Arguments
/// - `player`: gameplay player object.
/// - `out`: pointer to at least four `u32` (or `f32`) words that receive the
///   block.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes 16 bytes to `out`; calls the actor vtable `+0x3D4` and
/// [`fn_8004bf00`].
///
/// # Safety
/// `out` must be writable for 16 bytes and `player + 0x60` must hold a live
/// vtable.
///
/// # Confidence
/// high - the table offsets (`0x802F55B8`, `0x802F55D8`, `0x802F55F8`) and the
/// 16-byte copies were verified in `main.elf`.
pub unsafe fn fn_8004c0d0(player: usize, out: usize) {
    // observed 0x8004C108: `(-u | u) >> 31` produces 1 when the virtual result
    // is non-zero; multiplying by -0x10 turns it into +16 or 0.
    let variant = call_actor_slot1(player, 0x3D4);
    let offset = if variant != 0 { 0x10 } else { 0 };

    let pose = fn_8004bf00(player, 0);
    let base = match pose {
        0 => POSE_BLOCK_TABLE + offset,
        1 => POSE_BLOCK_TABLE + 0x20 + offset,
        2 => POSE_BLOCK_TABLE + 0x40 + offset,
        _ => return,
    };
    for i in 0..4 {
        platform::write_u32(out + i * 4, platform::read_u32(base + i * 4));
    }
}

// ---------------------------------------------------------------------------
// 0x8004C1E0 - scale the animation rate from the pose state
// ---------------------------------------------------------------------------

/// Scales `+0x11C` (animation rate) by one of `0.375`, `0.25` or `0.004`
/// according to the three-way pose state and the movement entry.
///
/// It only acts when [`fn_8004bf00`] returns `1`, or `2` with `param_2 == 1`.
/// With a zero target speed `+0x110`, a fast-animation or `0.5 <= |speed|`
/// gate chooses `0.375`, otherwise the rate becomes `0.004`. With a non-zero
