/// Calls the interface `+0x5C` method with the `f32` pair at `0x803714B0`,
/// writes `+0x14A4`, clears event flag `3`.
///
/// # Safety
/// `player + 0xDE8 -> +0x04` must be a live interface object.
///
/// # Confidence
/// high - the one-shot counter and both constants were verified.
pub unsafe fn fn_8004ac10(player: usize) {
    if platform::read_i32(player + 0x14A4) != 0 {
        return;
    }

    let sub = platform::read_u32(player + ACTOR_SUB) as usize;
    let interface = platform::read_u32(sub + 4) as usize;
    call_interface_slot_f32x3(
        interface,
        0x5C,
        platform::read_f32(EFFECT_C_803714B0),
        platform::read_f32(EFFECT_D_803714B4),
        0.0,
        0x93,
    );

    let count = platform::read_i32(player + 0x14A4);
    platform::write_u32(player + 0x14A4, (count + 1) as u32);
    platform::call2(0x8005_6CB0, player as u32, 3);
}

// ---------------------------------------------------------------------------
// 0x8004AD90 - probe the ground position and choose an effect
// ---------------------------------------------------------------------------

/// Probes `0x80069270` with the three floats at sub-object `+0xCC..+0xD4` and
/// compares the returned X against the player's X.
///
/// When the X coordinates are equal, `+0x348` becomes `1` (ground level
/// matched); otherwise it becomes `0`. The Ghidra C prints `<=` for this test,
/// but the instruction stream extracts only the `EQ` condition bit.
///
/// The one-shot counter `+0x14A4` then selects:
/// * `0`: send effect `0x91` (no match) or `0x90` (match), increment to `1`;
/// * `1`: call the class slot `+0x444`, feed the returned short to
///   `0x8015F340(player + 0x102, value, 0x800)` and, on success, increment to
///   `2` and clear event flag `3`.
///
/// # Original
/// - Ghidra: `FUN_8004AD90` at `0x8004AD90` (388 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004ad90_FUN_8004ad90.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x348`, `+0x14A4`, event flag `3`; performs an interface effect
/// call and two class calls.
///
/// # Safety
/// The probe global, the sub-object and the returned actor must be live.
///
/// # Confidence
/// medium - the equality test was corrected from `main.elf`; the exact
/// meaning of the probe result is inferred.
pub unsafe fn fn_8004ad90(player: usize) {
    let sub = platform::read_u32(player + ACTOR_SUB) as usize;
    let object = platform::read_u32(sub + 4) as usize;
    let mut probe = [
        platform::read_f32(object + 0xCC),
        platform::read_f32(object + 0xD0),
        platform::read_f32(object + 0xD4),
    ];
    let hit = platform::call2(
        0x8006_9270,
        GROUND_PROBE_80429D50 as u32,
        probe.as_mut_ptr() as u32,
    ) as usize;

    if hit != 0 {
        let mut out = [0.0f32; 2];
        let vtable = platform::read_u32(hit + ACTOR_CLASS_VTABLE) as usize;
        let method = platform::read_u32(vtable + 0x70) as usize;
        platform::call2(method, out.as_mut_ptr() as u32, hit as u32);

        // observed 0x8004ADF0..0x8004AE18: only the EQ bit is tested.
        if out[0] == platform::read_f32(player + ACTOR_POS) {
            platform::write_u8(player + 0x348, 1);
        } else {
            platform::write_u8(player + 0x348, 0);
        }
    }

    let stage = platform::read_i32(player + 0x14A4);
    if stage == 0 {
        let interface =
            platform::read_u32(platform::read_u32(player + ACTOR_SUB) as usize + 4) as usize;
        if platform::read_u8(player + 0x348) == 0 {
            call_interface_slot_f32x3(
                interface,
                0x5C,
                platform::read_f32(EFFECT_E_80371498),
                platform::read_f32(EFFECT_F_8037149C),
                0.0,
                0x91,
            );
        } else {
            call_interface_slot_f32x3(
                interface,
                0x5C,
                platform::read_f32(EFFECT_G_8037148C),
                platform::read_f32(EFFECT_H_80371490),
                0.0,
                0x90,
            );
        }
        platform::write_u32(player + 0x14A4, 1);
    } else if stage == 1 {
        let flags = platform::read_u8(player + 0x348);
        let raw = call_actor_slot(player, 0x444, flags as u32);
        let value = (raw as u16 as i16) as i32;
        if platform::call3(0x8015_F340, (player + 0x102) as u32, value as u32, 0x800) != 0 {
            platform::write_u32(player + 0x14A4, 2);
            platform::call2(0x8005_6CB0, player as u32, 3);
        }
    }
}

// ---------------------------------------------------------------------------
// 0x8004B730 - horizontal-speed target dispatcher
// ---------------------------------------------------------------------------

/// Recomputes the target horizontal speed `+0x110` from the movement state,
/// the model scale and the direction table at `0x8042B840`.
///
/// The early-out is [`fn_8004b640`] or event flag `0x96`. With no movement
/// entry the function zeroes `+0x110`; if the actor is nearly stopped it also
/// zeroes `+0x10C`, otherwise pose state `1` selects [`fn_8004b5e0`].
///
/// The entry branch uses three candidate values:
/// * `scale * model[0]` (the model's first float),
/// * `scale * model[8]` (the model's `+0x08` float),
/// * `abs(speed) * scale`.
///
/// It picks `model[8]` when its magnitude is within the speed or the
/// alternate-model query says so; otherwise it picks `model[0]` when
/// `abs(speed)` reaches `abs(model[0])`, and the speed-scaled value otherwise.
/// The flag-bit-0 branch instead combines the model value with
/// [`fn_8004b4c0`]. A final clamp keeps `abs(+0x10C)` within `model[8]` unless
/// event flag `0x88` is set.
///
/// # Original
/// - Ghidra: `FUN_8004B730` at `0x8004B730` (624 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004b730_FUN_8004b730.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x110`, `+0x10C`, `+0x11C` indirectly through [`fn_8004b4c0`];
/// queries `0x8005E7A0`, `0x80056CF0`, `0x8005E610` and `0x80057650`.
///
/// # Safety
/// `player + 0xEA4` must be a live movement-state object and the model getter
/// must return a readable transform.
///
/// # Confidence
/// high - the Ghidra C was checked against the full instruction stream,
/// including the `bgt`/`blt` condition bits at `0x8004B7F8..0x8004B834`.
pub unsafe fn fn_8004b730(player: usize) {
    if fn_8004b640(player) != 0 || platform::call2(0x8005_6CF0, player as u32, 0x96) != 0 {
        return;
    }

    let mut entry = [0u32; 3];
    let has_entry = platform::call2(
        0x8005_E7A0,
        (player + ACTOR_MOVE_STATE) as u32,
        entry.as_mut_ptr() as u32,
    ) != 0;

    if !has_entry {
        platform::write_f32(player + ACTOR_SPEED_TARGET, 0.0);
        if fn_8004b160(player) != 0 {
            platform::write_f32(player + ACTOR_SPEED, 0.0);
        } else if fn_8004bf00(player, 0) == 1 {
            platform::write_f32(player + ACTOR_SPEED_TARGET, fn_8004b5e0(player));
        }
    } else if (platform::read_u32(player + ACTOR_FLAGS) & 1) == 0 {
        let abs_speed = platform::read_f32(player + ACTOR_SPEED).abs();
        let scale = platform::read_f32(ANIM_DIR_SCALE + (entry[0] as usize) * 4);

        let model_a = platform::call1(0x8005_7650, player as u32) as usize;
        let model_first = scale * platform::read_f32(model_a);

        let model_b = platform::call1(0x8005_7650, player as u32) as usize;
        let scaled_speed = abs_speed * scale;
        let model_eighth = scale * platform::read_f32(model_b + 8);

        if model_eighth.abs() <= abs_speed
            || platform::call1(0x8005_E610, (player + ACTOR_MOVE_STATE) as u32) != 0
        {
            platform::write_f32(player + ACTOR_SPEED_TARGET, model_eighth);
        } else if abs_speed <= model_first.abs() {
            platform::write_f32(player + ACTOR_SPEED_TARGET, model_first);
        } else {
            platform::write_f32(player + ACTOR_SPEED_TARGET, scaled_speed);
        }
    } else {
        let alternate =
            platform::call1(0x8005_E610, (player + ACTOR_MOVE_STATE) as u32) != 0;
        let model = platform::call1(0x8005_7650, player as u32) as usize;
        let model_value = if alternate {
            platform::read_f32(model + 8)
        } else {
            platform::read_f32(model)
        };
        let scale = platform::read_f32(ANIM_DIR_SCALE + (entry[0] as usize) * 4);
        let product = scale * model_value;
        let rate = fn_8004b4c0(player, entry[0] & 0xFF);
        platform::write_f32(player + ACTOR_SPEED_TARGET, product * rate);
    }

    if (platform::read_u32(player + ACTOR_FLAGS) & 1) == 0
        && platform::call2(0x8005_6CF0, player as u32, 0x88) == 0
    {
        let abs_speed = platform::read_f32(player + ACTOR_SPEED).abs();
        let model = platform::call1(0x8005_7650, player as u32) as usize;
        let limit = platform::read_f32(model + 8);
        if limit < abs_speed {
            let speed = platform::read_f32(player + ACTOR_SPEED);
            if 0.0 <= speed {
                platform::write_f32(player + ACTOR_SPEED, limit);
            } else {
                platform::write_f32(player + ACTOR_SPEED, -limit);
            }
        }
    }
}

// ---------------------------------------------------------------------------
// 0x8004BC80 - animation-rate selection from pose and speed
// ---------------------------------------------------------------------------

/// Chooses the animation rate `+0x11C` from the pose block at `0x8004BF80`
/// and the direction scale table at `0x8042B840`.
///
/// When `abs(+0x10C)` exceeds the model's `+0x08` float the rate becomes
/// `0.75`. Otherwise the nine-float pose block is copied and the movement
/// entry `0x8005E7A0(+0xEA4, 0)` decides between two sets of thresholds:
///
/// * without an entry, a negative speed*scale selects pose word 2, a slow
///   actor selects word 1, and a fast actor selects word 0; state `1` with
///   `abs(speed) < 0.5` overrides with `0.004`, and event flag `0x89`
///   multiplies the result by `3.0`;
/// * with an entry, the pose word is selected by thresholds at
///   `0.5`, `model[0]` and `model[+4]`, using the absolute target speed as a
///   tie-breaker; the negative product path selects pose word 3 and applies
///   the same `3.0` flag boost.
///
/// # Original
/// - Ghidra: `FUN_8004BC80` at `0x8004BC80` (636 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004bc80_FUN_8004bc80.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x11C`; calls [`fn_8004bf00`], [`fn_8004bf80`], the model getter
/// and the event-flag test.
///
/// # Safety
/// `player + 0xEA4` must be live and the pose block must contain nine floats.
///
/// # Confidence
/// high - every threshold and pose-word index was checked in `main.elf`.
pub unsafe fn fn_8004bc80(player: usize) {
    let abs_speed = platform::read_f32(player + ACTOR_SPEED).abs();
    let model = platform::call1(0x8005_7650, player as u32) as usize;
    if read_f32(model + 8) < abs_speed {
        platform::write_f32(player + ACTOR_ANIM_RATE, ANIM_RATE_075);
        return;
    }

    let state = fn_8004bf00(player, 0);
    let mut pose = [0.0f32; 9];
    fn_8004bf80(player, pose.as_mut_ptr() as usize);

    let has_entry = platform::call2(
        0x8005_E7A0,
        (player + ACTOR_MOVE_STATE) as u32,
        0,
    ) != 0;

    if !has_entry {
        let direction = platform::read_f32(player + ACTOR_SPEED)
            * platform::read_f32(
                ANIM_DIR_SCALE + (platform::read_u8(player + 0x348) as usize) * 4,
            );
        let rate = if 0.0 <= direction {
            let abs_speed = platform::read_f32(player + ACTOR_SPEED).abs();
            let model = platform::call1(0x8005_7650, player as u32) as usize;
            if platform::read_f32(model) <= abs_speed {
                pose[0]
            } else {
                pose[1]
            }
        } else {
            pose[2]
        };
        platform::write_f32(player + ACTOR_ANIM_RATE, rate);

        if state == 1 && platform::read_f32(player + ACTOR_SPEED).abs() < SPEED_HALF {
            platform::write_f32(player + ACTOR_ANIM_RATE, ANIM_RATE_STOP);
        }
        if platform::call2(0x8005_6CF0, player as u32, 0x89) != 0 {
            let rate = platform::read_f32(player + ACTOR_ANIM_RATE);
            platform::write_f32(player + ACTOR_ANIM_RATE, ANIM_RATE_BOOST * rate);
        }
        return;
    }

    let direction = platform::read_f32(player + ACTOR_SPEED)
        * platform::read_f32(
            ANIM_DIR_SCALE + (platform::read_u8(player + 0x348) as usize) * 4,
        );
    if 0.0 <= direction {
        let abs_speed = platform::read_f32(player + ACTOR_SPEED).abs();
        let abs_target = platform::read_f32(player + ACTOR_SPEED_TARGET).abs();

        let rate = if SPEED_HALF <= abs_speed {
            let model = platform::call1(0x8005_7650, player as u32) as usize;
            if platform::read_f32(model) <= abs_speed {
                let model = platform::call1(0x8005_7650, player as u32) as usize;
                if platform::read_f32(model + 4) <= abs_speed {
                    let model = platform::call1(0x8005_7650, player as u32) as usize;
                    if platform::read_f32(model + 4) <= abs_target {
                        pose[8]
                    } else {
                        pose[0]
                    }
                } else {
                    let model = platform::call1(0x8005_7650, player as u32) as usize;
                    if platform::read_f32(model + 4) <= abs_target {
                        pose[7]
                    } else {
                        pose[0]
                    }
                }
            } else if platform::call1(0x8005_E610, (player + ACTOR_MOVE_STATE) as u32) == 0 {
                pose[5]
            } else {
                pose[6]
            }
        } else {
            pose[4]
        };
        platform::write_f32(player + ACTOR_ANIM_RATE, rate);
    } else {
        platform::write_f32(player + ACTOR_ANIM_RATE, pose[3]);
        if platform::call2(0x8005_6CF0, player as u32, 0x89) != 0 {
            let rate = platform::read_f32(player + ACTOR_ANIM_RATE);
            platform::write_f32(player + ACTOR_ANIM_RATE, ANIM_RATE_BOOST * rate);
        }
    }
}

// ---------------------------------------------------------------------------
// 0x8004C310 - alternate animation-rate selection (seven-entry table)
// ---------------------------------------------------------------------------

/// Chooses `+0x11C` from the seven-entry rate table at `0x802F5580`.
///
/// The table has two halves of seven floats; the model-variant slot `+0x3D4`
/// selects the second half when non-zero. A missing movement entry selects
/// entry `0`; a negative speed*scale selects entry `6`; otherwise the
/// thresholds `0.5`, `model[0]` and `model[+4]` select entries `1..5`.
///
/// # Original
/// - Ghidra: `FUN_8004C310` at `0x8004C310` (320 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004c310_FUN_8004c310.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x11C`; calls the model-variant slot, `0x8005E7A0`,
/// `0x80057650` and `0x8005E610`.
///
/// # Safety
/// `player + 0xEA4` must be live and the model getter must return a readable
/// transform.
///
/// # Confidence
/// high - the two table halves and all five threshold branches were checked.
pub unsafe fn fn_8004c310(player: usize) {
    let variant = call_actor_slot1(player, 0x3D4);
    // observed 0x8004C35C/0x8004C360: `mulli ...,28` adds +0x1C for a
    // non-zero variant; the Ghidra C prints the same selection as `-0x1C`.
    let table = ALT_ANIM_RATE_TABLE + if variant != 0 { 0x1C } else { 0 };

    // observed: the Ghidra stack slot is `int[4]`; only word 0 is read.
    let mut entry = [0u32; 4];
    let has_entry = platform::call2(
        0x8005_E7A0,
        (player + ACTOR_MOVE_STATE) as u32,
        entry.as_mut_ptr() as u32,
    ) != 0;

    if !has_entry {
        platform::write_f32(player + ACTOR_ANIM_RATE, platform::read_f32(table));
        return;
    }

    let direction = platform::read_f32(player + ACTOR_SPEED)
        * platform::read_f32(ANIM_DIR_SCALE + (entry[0] as usize) * 4);
    if direction < 0.0 {
        platform::write_f32(player + ACTOR_ANIM_RATE, platform::read_f32(table + 0x18));
        return;
    }

    let abs_speed = platform::read_f32(player + ACTOR_SPEED).abs();
    if abs_speed < SPEED_HALF {
        platform::write_f32(player + ACTOR_ANIM_RATE, platform::read_f32(table + 0x04));
        return;
    }

    let model = platform::call1(0x8005_7650, player as u32) as usize;
    if platform::read_f32(model) <= abs_speed {
        let model = platform::call1(0x8005_7650, player as u32) as usize;
        let offset = if platform::read_f32(model + 4) <= abs_speed {
            0x14
        } else {
            0x10
        };
        platform::write_f32(player + ACTOR_ANIM_RATE, platform::read_f32(table + offset));
    } else if platform::call1(0x8005_E610, (player + ACTOR_MOVE_STATE) as u32) == 0 {
        platform::write_f32(player + ACTOR_ANIM_RATE, platform::read_f32(table + 0x08));
    } else {
        platform::write_f32(player + ACTOR_ANIM_RATE, platform::read_f32(table + 0x0C));
    }
}

// ---------------------------------------------------------------------------
// 0x8004C780 - knockback/slide accumulator
// ---------------------------------------------------------------------------

/// Accumulates a signed slide value at `+0x14C0` while the actor is in a
/// knockback state.
///
/// The lookup `0x80162D50(0x79, 0)` supplies the state object; when it is
/// absent, or event flag `0xA0` is clear, or either movement bit
/// `0x10000000`/`0x08000000` is set, the accumulator is cleared.
///
/// Otherwise a transfer curve is applied to the object's `+0x394` float:
/// * `0.5 * curve` is the per-step delta,
/// * `3.0 * abs(curve)` is the limit, further scaled by `0.55` or `0.45`
///   when the flag-bit-0 branch is taken.
///
/// The accumulator is zeroed when it points into a blocked direction
/// (positive with flag `0x40`, or negative with flag `0x20`). Normal control
/// moves the accumulator when speed and accumulator have the same sign,
/// otherwise it moves the speed; the flag-bit-0 branch transfers the whole
/// accumulator into speed and starts a three-frame timer at `+0x14BC`.
///
/// # Original
/// - Ghidra: `FUN_8004C780` at `0x8004C780` (524 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004c780_FUN_8004c780.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x14C0`, `+0x10C`, `+0x14BC`, event flag `0x43`; calls
/// `0x80162D50`, `0x80056CF0`, `0x80056C70`, `0x80056CB0` and
/// [`fn_8004c700`].
///
/// # Safety
/// The state object returned by `0x80162D50` must be live when non-zero.
///
/// # Confidence
/// high - the constants `0.45/0.55/0.5/3.0` and all four branches were
/// checked in `main.elf`.
pub unsafe fn fn_8004c780(player: usize) {
    let object = platform::call2(0x8016_2D50, 0x79, 0) as usize;
    if object == 0 {
        platform::write_f32(player + 0x14C0, 0.0);
        return;
    }

    let flags = platform::read_u32(player + ACTOR_FLAGS);
    if platform::call2(0x8005_6CF0, player as u32, 0xA0) == 0
        || (flags & 0x1800_0000) != 0
    {
        platform::write_f32(player + 0x14C0, 0.0);
        return;
    }

    let curve = fn_8004c700(platform::read_f32(object + 0x394));
    let delta = SPEED_HALF * curve;
    let mut limit = ANIM_RATE_BOOST * curve.abs();
    let mut value = platform::read_f32(player + 0x14C0);

    if (0.0 < value && (flags & 0x40) != 0) || (value < 0.0 && (flags & 0x20) != 0) {
        value = 0.0;
    }

    if (flags & 1) == 0 {
        if platform::call2(0x8005_6CF0, player as u32, 0x43) == 0 {
            platform::call2(0x8005_6C70, player as u32, 0x43);
        }

        if platform::read_i32(player + 0x14BC) == 0 {
            let speed = platform::read_f32(player + ACTOR_SPEED);
            if 0.0 <= speed * value {
                value += delta;
            } else {
                platform::write_f32(player + ACTOR_SPEED, speed + delta);
            }
        } else {
            let frames = platform::read_i32(player + 0x14BC);
            platform::write_u32(player + 0x14BC, (frames - 1) as u32);
        }
    } else {
        if platform::call2(0x8005_6CF0, player as u32, 0x43) != 0 {
            platform::call2(0x8005_6CB0, player as u32, 0x43);
            let transferred = value;
            value = 0.0;
            let speed = platform::read_f32(player + ACTOR_SPEED);
            platform::write_f32(player + ACTOR_SPEED, speed + transferred);
        }

        let factor = if platform::call2(0x8005_6CF0, player as u32, 0x5B) != 0 {
            KNOCKBACK_LIMIT_SHORT
        } else {
            KNOCKBACK_LIMIT_LONG
        };
        limit *= factor;
        platform::write_u32(player + 0x14BC, 3);
        value += delta;
    }

    if limit < value {
        value = limit;
    } else if value < -limit {
        value = -limit;
    }
    platform::write_f32(player + 0x14C0, value);
}

// ---------------------------------------------------------------------------
// 0x8004CA60 - state-indexed sound selection
// ---------------------------------------------------------------------------

/// Selects a sound id from the state-indexed table at `0x803546C4`.
///
/// State `5` bypasses the table and calls `0x80057FD0(player, 0x11E,
/// (short)abs(speed), 0)`. For every other state the function lazily fills the
/// thirteen-entry table with ids `0xE5`/`0xE7`/`0xE8`/`0xE9`, guarded by the
/// ready byte at `0x80429C89`, then calls `0x80057F60(player, id, 0)`.
///
/// # Original
/// - Ghidra: `FUN_8004CA60` at `0x8004CA60` (208 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004ca60_FUN_8004ca60.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Fills the BSS table and its ready byte on first use; calls one of the two
/// sound helpers.
///
/// # Safety
/// The player state must index the table in `0..13`.
///
/// # Confidence
/// high - all thirteen ids and the `0x11E` argument were read from
/// `main.elf`.
pub unsafe fn fn_8004ca60(player: usize) {
    if platform::read_i32(player + ACTOR_STATE) == 5 {
        let speed = platform::read_f32(player + ACTOR_SPEED).abs();
        platform::call4(
            0x8005_7FD0,
            player as u32,
            0x11E,
            (speed as i32 as i16 as i32) as u32,
            0,
        );
        return;
    }

    if platform::read_u8(STATE_SOUND_READY) == 0 {
        let ids = [
            0xE5u32, 0xE8, 0xE9, 0xE7, 0xE5, 0xE5, 0xE5, 0xE9, 0xE5, 0xE9, 0xE5, 0xE5,
            0xE5,
        ];
        let mut index = 0;
        while index < ids.len() {
            platform::write_u32(STATE_SOUND_TABLE + index * 4, ids[index]);
            index += 1;
        }
        platform::write_u8(STATE_SOUND_READY, 1);
    }

    let state = platform::read_i32(player + ACTOR_STATE) as usize;
    let id = platform::read_u32(STATE_SOUND_TABLE + state * 4);
    platform::call3(0x8005_7F60, player as u32, id, 0);
}

// ---------------------------------------------------------------------------
// 0x8004D5C0 - state-indexed effect after the damage predicate
// ---------------------------------------------------------------------------

/// Plays a state-indexed effect id when the damage predicate is active.
///
/// The function returns unless
/// * [`fn_8004dd00`] is non-zero or flag bit `0` of `+0x10D4` is set,
/// * the global mode at `0x8042A204` is not `2`, and
/// * `0x800D6AB0(player->+0xDE8->+4)` is non-zero.
///
/// State `5` selects the single id `0xE1`; every other state lazily fills the
/// thirteen-entry table at `0x8035472C` (guarded by `0x80429C8B`) and calls
/// `0x80058110(player, id)`.
///
/// # Original
/// - Ghidra: `FUN_8004D5C0` at `0x8004D5C0` (300 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004d5c0_FUN_8004d5c0.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Fills the BSS table and ready byte on first use; calls the damage predicate
/// and one effect helper.
///
/// # Safety
/// `player + 0xDE8 -> +0x04` must be readable and the state must index the
/// table in `0..13`.
///
/// # Confidence
/// high - the gate order, both tables and all ids were read from `main.elf`.
pub unsafe fn fn_8004d5c0(player: usize) {
    let damaged = fn_8004dd00(player) != 0
        || (platform::read_u32(player + ACTOR_FLAGS) & 1) != 0;
    if !damaged || platform::read_i32(GLOBAL_MODE_8042A204) == 2 {
        return;
    }

    let sub = platform::read_u32(player + ACTOR_SUB) as usize;
    let object = platform::read_u32(sub + 4);
    if platform::call1(0x800D_6AB0, object) == 0 {
        return;
    }

    if platform::read_i32(player + ACTOR_STAGE) == 5 {
        platform::call2(0x8005_8110, player as u32, 0xE1);
        return;
    }

    if platform::read_u8(STATE_EFFECT_READY) == 0 {
        let ids = [
            199u32, 207, 203, 199, 197, 209, 215, 211, 213, 203, 217, 205, 219,
        ];
        let mut index = 0;
        while index < ids.len() {
            platform::write_u32(STATE_EFFECT_TABLE + index * 4, ids[index]);
            index += 1;
        }
        platform::write_u8(STATE_EFFECT_READY, 1);
    }

    let state = platform::read_i32(player + ACTOR_STATE) as usize;
    let id = platform::read_u32(STATE_EFFECT_TABLE + state * 4);
    platform::call2(0x8005_8110, player as u32, id);
}

// ---------------------------------------------------------------------------
// 0x8004DB40 - damage/state predicate dispatcher
// ---------------------------------------------------------------------------

/// Evaluates one of six named damage/state modes.
///
/// * `1`: `+0x1460` is non-zero and event flag `4` is set.
/// * `2`: class slot `+0x120` is non-zero.
/// * `3`: event flag `0x76` is set or `+0x1460` is non-zero.
/// * `4`: class slot `+0xE0` is zero, either flag `0x72`/`0x71` is set, and
///   the byte at `+0x3F4` is below `5`.
/// * `5`: class slot `+0xE0` is non-zero, either flag is set, and the byte is
///   below `8`.
/// * `6`: either flag is set and the byte is exactly `8`.
///
/// Any other mode returns `0`.
///
/// # Original
/// - Ghidra: `FUN_8004DB40` at `0x8004DB40` (432 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004db40_FUN_8004db40.c`
///
/// # Arguments
/// - `player`: gameplay player object.
/// - `mode`: selector `1..6`.
///
/// # Returns
/// `1` when the selected predicate holds, `0` otherwise.
///
/// # Side effects
/// Calls `crate::runtime::cpp::fn_8004de30`, the event-flag test and one class
/// slot depending on the mode.
///
/// # Safety
/// `+0x60` must hold a vtable with the `+0x120`/`+0xE0` slots used here.
///
/// # Confidence
/// high - the mode order and the two byte thresholds were checked against the
/// instruction stream.
pub unsafe fn fn_8004db40(player: usize, mode: u32) -> u32 {
    if mode == 1 {
        if crate::runtime::cpp::fn_8004de30(player) != 0
            && platform::call2(0x8005_6CF0, player as u32, 4) != 0
        {
            return 1;
        }
        return 0;
    }

    if mode == 2 {
        return (call_actor_slot1(player, 0x120) != 0) as u32;
    }

    if mode == 3 {
        if platform::call2(0x8005_6CF0, player as u32, 0x76) != 0
            || crate::runtime::cpp::fn_8004de30(player) != 0
        {
            return 1;
        }
        return 0;
    }

    if mode == 4 {
        if call_actor_slot1(player, 0xE0) == 0 {
            // observed: `||` preserves the C short-circuit (0x71 is only read
            // when 0x72 is clear).
            let flag = platform::call2(0x8005_6CF0, player as u32, 0x72) != 0
                || platform::call2(0x8005_6CF0, player as u32, 0x71) != 0;
            if flag && platform::read_u8(player + 0x3F4) < 5 {
                return 1;
            }
        }
        return 0;
    }

    if mode == 5 {
        if call_actor_slot1(player, 0xE0) != 0 {
            let flag = platform::call2(0x8005_6CF0, player as u32, 0x72) != 0
                || platform::call2(0x8005_6CF0, player as u32, 0x71) != 0;
            if flag && platform::read_u8(player + 0x3F4) < 8 {
                return 1;
            }
        }
        return 0;
    }

    if mode == 6 {
        let flag = platform::call2(0x8005_6CF0, player as u32, 0x72) != 0
            || platform::call2(0x8005_6CF0, player as u32, 0x71) != 0;
        if flag && platform::read_u8(player + 0x3F4) == 8 {
            return 1;
        }
    }

    0
}

