// ---------------------------------------------------------------------------
// 0x8004F300 - animation-result dispatcher
// ---------------------------------------------------------------------------

/// Runs the animation-result query for the current movement mode and, on
/// success, forwards the recovered face id to [`fn_8004f480`].
///
/// Event flag `0x7E` short-circuits the whole function. Modes `2`/`3` use the
/// six-argument query `0x80071A60` with a pair of floats chosen from flags
/// `0x3A`/`0x17`; mode `1` and mode `0` use the alternate queries based on the
/// movement state at `player + 0xEA4`.
///
/// # Original
/// - Ghidra: `FUN_8004F300` at `0x8004F300` (376 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004f300_FUN_8004f300.c`
///
/// # Arguments
/// - `player`: gameplay player object.
/// - `mode`: animation/movement mode (`0`, `1`, `2` or `3`).
///
/// # Returns
/// `1` when the query result was `1` and [`fn_8004f480`] accepted the face id;
/// `0` otherwise.
///
/// # Side effects
/// Calls the animation controller at `player + 0x1EC` and may start a face
/// change through [`fn_8004f480`].
///
/// # Safety
/// `player + 0x1EC` must be a live animation controller and
/// `player + 0x3FC` a three-float position buffer.
///
/// # Confidence
/// high - the branch tree and both float choices were read from `main.elf`.
pub unsafe fn fn_8004f300(player: usize, mode: u32) -> u32 {
    if fn_80056cf0(player, 0x7E) != 0 {
        return 0;
    }

    let mut out = [0u32; 3];
    let mut result = 0u32;

    if mode.wrapping_sub(2) < 2 {
        // observed 0x8004F3BC..0x8004F400: the pair starts at (0, 0) and is
        // replaced by (2, -2) for flag 0x3A or (8, 8) for flag 0x17.
        let mut first = W18_ZERO;
        let mut second = W18_ZERO;
        if fn_80056cf0(player, 0x3A) != 0 {
            first = W18_TWO;
            second = W18_NEG_TWO;
        } else if fn_80056cf0(player, 0x17) != 0 {
            first = W18_EIGHT;
            second = W18_EIGHT;
        }
        result = w18_anim_query(
            first,
            second,
            player + 0x1EC,
            player + 0x3FC,
            platform::read_u8(player + 0x348) as u32,
            out.as_mut_ptr(),
        );
    } else if mode == 1 {
        if platform::call1(0x8005_E500, (player + 0xEA4) as u32) != 0 {
            result = w18_anim_query_alt1(player + 0x1EC, player + 0x3FC, out.as_mut_ptr());
        }
    } else if mode == 0 {
        if platform::call1(0x8005_E4F0, (player + 0xEA4) as u32) != 0 {
            result = w18_anim_query_alt2(player + 0x1EC, player + 0x3FC, out.as_mut_ptr());
        }
    }

    if result == 1 && fn_8004f480(player, out[0], mode) != 0 {
        1
    } else {
        0
    }
}

// ---------------------------------------------------------------------------
// 0x8004F480 - face/bonus application
// ---------------------------------------------------------------------------

/// Applies one face/bonus id to the player and reports whether the change was
/// accepted.
///
/// The id is stored at `+0x3F8`, resolved through the stage record and
/// `0x8008E3D0`, and classified into mode `1`/`2`/`3` from the entry's
/// `+0x10` halfword. Each mode talks to the resource manager
/// (`0x800CFDE0`/`0x800CFCA0`), the spawn manager (`0x800D90C0`) and finally
/// [`fn_8004e290`].
///
/// # Original
/// - Ghidra: `FUN_8004F480` at `0x8004F480` (484 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004f480_FUN_8004f480.c`
///
/// # Arguments
/// - `player`: gameplay player object.
/// - `id`: face/bonus id, stored at `+0x3F8`; only the low byte is used for
///   lookups.
/// - `selector`: index into the interface table at `0x80308450`.
///
/// # Returns
/// `1` when the change was committed, `0` when it was deferred or rejected.
///
/// # Side effects
/// Writes `+0x3F8` and `+0x414`; may call `0x800CFCA0`, `0x800D90C0` and
/// [`fn_8004e290`].
///
/// # Safety
/// The manager pointers at `0x80429C94`/`0x80429FC0` and the stage record must
/// be valid.
///
/// # Confidence
/// high - every branch and the `entry + 1` mode word were checked.
pub unsafe fn fn_8004f480(player: usize, id: u32, selector: u32) -> u32 {
    platform::write_u32(player + 0x3F8, id);

    let record = w18_stage_record();
    let entry = platform::call2(0x8008_E3D0, record as u32, id & 0xFF) as usize;

    // observed 0x8004F4D8: the default mode is `1`.
    platform::write_u32(player + 0x414, 1);
    let entry_flags = platform::read_u16(entry + 0x10);
    if entry_flags & 0x0008 != 0 {
        platform::write_u32(player + 0x414, 2);
    } else if entry_flags & 0x0004 != 0 {
        platform::write_u32(player + 0x414, 3);
    }

    let mode = platform::read_u32(player + 0x414);
    let players = platform::read_u32(PLAYER_ARRAY_8042A1C8) as usize;
    let slot = platform::read_u8(players + 0x120E) as u32;
    let interface = platform::read_u32(W18_IFACE_TABLE_80308450 + selector as usize * 4) as usize;

    if mode == 1 {
        let resource = platform::read_u32(W18_RESOURCE_80429FC0);
        if platform::call3(0x800C_FDE0, resource, slot, id & 0xFF) != 0 {
            return 0;
        }
        let manager = platform::read_u32(MANAGER_80429C94) as usize;
        if platform::read_u32(manager + 0x5C) != 0 {
            return 0;
        }
        platform::call4(0x800C_FCA0, resource, slot, id & 0xFF, 5);
        if read_i8(entry + 0xB) == 0x16 {
            fn_8004e290(player, W18_IFACE_80354AAC, 0);
        } else {
            fn_8004e290(player, interface, 0);
        }
        1
    } else if mode == 2 {
        platform::call1(0x800D_90C0, platform::read_u8(entry + 0xF) as u32);
        fn_8004e290(player, interface, 0);
        1
    } else if mode == 3 {
        if read_i8(entry + 0xB) == 0x16 {
            fn_8004e290(player, W18_IFACE_80354AAC, selector);
        } else {
            fn_8004e290(player, interface, 0);
        }
        1
    } else {
        0
    }
}

// ---------------------------------------------------------------------------
// 0x8004F740 - face-change pose reset
// ---------------------------------------------------------------------------

/// Stores a face-change mode and resets the pose, effect vector and motion
/// rates for the new face.
///
/// The animation name `0x8035425C` is restarted, the interface effect gets
/// `(0, 5, 85)` with id `0`, and `+0x424`/`+0x428` receive one of four
/// constants depending on the mode at `+0x414` and the character byte at
/// `+0x38C`.
///
/// # Original
/// - Ghidra: `FUN_8004F740` at `0x8004F740` (280 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8004f740_FUN_8004f740.c`
///
/// # Arguments
/// - `player`: gameplay player object.
/// - `mode`: face-change mode, stored as a byte at `+0x418`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x418`, `+0x424`, `+0x428`; calls the `+0x294`, `+0x280` and
/// `+0x5C` virtual slots and possibly [`fn_8004e050`].
///
/// # Safety
/// `player + 0xDE8` must reach the effect interface object.
///
/// # Confidence
/// high - the four `+0x424` constants and both gate fields were read from
/// `main.elf`.
pub unsafe fn fn_8004f740(player: usize, mode: u32) {
    platform::write_u8(player + 0x418, mode as u8);
    let _ = call_actor_slot3(player, 0x294, ANIM_NAME_8035425C as u32, 0);

    let effect = platform::read_u32(platform::read_u32(player + ACTOR_SUB) as usize + 4) as usize;
    let _ = call_interface_slot_f32x3(effect, 0x5C, W18_ZERO, W18_FIVE, W18_EIGHTY_FIVE, 0);

    if platform::read_u32(player + 0x414) == 2 {
        platform::write_f32(
            player + 0x424,
            if mode == 0 { W18_ZERO } else { W18_NEG_THIRTY_FOUR },
        );
    } else if mode == 0 {
        platform::write_f32(player + 0x424, W18_TWO);
    } else if platform::read_u8(player + 0x38C) == 2 {
        platform::write_f32(player + 0x424, W18_NEG_SIXTEEN);
    } else {
        platform::write_f32(player + 0x424, W18_NEG_TEN);
    }

    platform::write_f32(player + 0x428, W18_ZERO);

    if platform::read_u32(player + 0x414) == 1
        && platform::read_u32(W18_MODE_80429CA0) == 1
    {
        fn_8004e050(player);
    }

    let _ = call_actor_slot1(player, 0x280);
}

