// ---------------------------------------------------------------------------
// 0x80050E60 - airborne throw/carry hand-off
// ---------------------------------------------------------------------------

/// Hands an airborne player to the carry/throw manager at the given position.
///
/// When manager word `+0x10` has bit `0x04` clear, the function writes the
/// position block at `player + 0x3FC`, starts the `0x8035421C` animation and
/// the `0x80354BAC` interface, resolves the actor slot through `0x8005B780`
/// and, when the slot is free, reserves it and probes the ground below the
/// start position. It then asks the character's `+0xE0` virtual slot whether
/// the throw is allowed and updates the manager counters.
///
/// # Original
/// - Ghidra: `FUN_80050E60` at `0x80050E60` (540 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80050e60_FUN_80050e60.c`
///
/// # Arguments
/// - `amount`: horizontal offset/height forwarded to the position block.
/// - `player`: gameplay player object.
/// - `position`: three-float source position; only `[0]` and `[1]` are used.
/// - `param_4`: value stored at `manager + 0x14`.
///
/// # Returns
/// `0xFFFFFFFF` in every path, matching the single `-1` return block.
///
/// # Side effects
/// Writes the position block, `+0x430`, the manager fields `+0x14`, `+0x42`,
/// `+0x48..+0x50`, `+0x80`, and calls the sound/spawn helpers.
///
/// # Safety
/// The manager at `0x80429C94` and the effect interface at `player+0xDE8`
/// must be valid.
///
/// # Confidence
/// high - the register-level float order and the `man+0x10 & 4` gate were
/// checked against `main.elf`.
pub unsafe fn fn_80050e60(
    amount: f32,
    player: usize,
    position: *const f32,
    param_4: u32,
) -> u32 {
    let manager = platform::read_u32(MANAGER_80429C94) as usize;
    if platform::read_u32(manager + 0x10) & 0x04 != 0 {
        return 0xFFFF_FFFF;
    }

    let x = unsafe { *position };
    let y = unsafe { *position.add(1) };
    let index = read_i8(player + ACTOR_OWNER);

    platform::write_f32(player + ACTOR_POS, x);
    let _ = call_actor_slot3(player, 0x294, W18_ANIM_NAME_8035421C as u32, 0);
    fn_8004e290(player, W18_IFACE_80354BAC, 0);

    platform::write_f32(player + 0x3FC, amount);
    platform::write_f32(player + 0x400, y);
    platform::write_f32(player + 0x404, W18_EIGHTY + x);

    let slot = platform::call2(0x8005_B780, manager as u32, index as i32 as u32);
    platform::write_u32(player + 0x430, slot);

    if slot == 0 {
        platform::call3(0x8005_B5C0, manager as u32, 1, 0);
        platform::write_u32(manager + 0x14, param_4);

        // observed 0x80050F28..0x80050F68: the probe point is
        // (amount - 112, y, 5500) and the result replaces the middle word.
        let mut probe = [amount - W18_ONE_HUNDRED_TWELVE, y, W18_FIVE_THOUSAND_FIVE_HUNDRED];
        platform::write_u32(manager + 0x80, index as i32 as u32);
        let mut ground = 0.0f32;
        let found = w18_ground_probe(
            probe.as_ptr(),
            &mut ground,
            platform::read_u8(player + 0x38F) as u32,
            1,
            0xFFFF_FFFF,
        );
        if found != 0 {
            probe[1] = W18_ONE_HUNDRED_TWELVE + ground;
        }
        platform::write_f32(manager + 0x48, probe[0]);
        platform::write_f32(manager + 0x4C, probe[1]);
        platform::write_f32(manager + 0x50, probe[2]);
    }

    let mut held = false;
    let item = platform::call1(0x8005_F900, index as i32 as u32) as usize;
    if item != 0 && call_actor_slot1(item, 0xE0) != 0 {
        held = true;
    }

    if held {
        platform::write_u8(manager + 0x42, 1);
        platform::call2(0x800B_3780, index as i32 as u32, 8);
    } else if platform::read_u32(player + 0x430) != 0
        && platform::read_u32(player + 0x430) + 1 == call0_u32(0x8005_FEF0)
    {
        platform::call1(0x800C_E8C0, platform::read_u32(W18_SOUND_80429FB0));
    }

    let count_a = call0_u32(0x8006_0010);
    let count_b = call0_u32(0x8005_FEF0);
    if count_b.wrapping_add(count_a) == platform::read_u32(player + 0x430).wrapping_add(1) {
        platform::call1(0x8005_B810, manager as u32);
    }

    0xFFFF_FFFF
}

