    let z = read_f32(player + 0xB4);
    let y = read_f32(player + 0xB0);
    let mut probe = [fn_80051420(player), y, z];

    let base = probe.as_mut_ptr();
    let _ = w18_ground_probe(
        base,
        base.add(1),
        platform::read_u8(player + 0x38F) as u32,
        1,
        0xFFFF_FFFF,
    );

    platform::write_u16(player + 0x102, 0x4000);
    platform::write_u8(player + 0x3F4, 4);

    let effect = platform::read_u32(platform::read_u32(player + ACTOR_SUB) as usize + 4) as usize;
    let _ = call_interface_slot_f32x3(
        effect,
        0x5C,
        read_f32(W18_EFFECT_X_803711EC),
        read_f32(W18_EFFECT_Y_803711F0),
        W18_ZERO,
        0x58,
    );

    let manager = platform::read_u32(MANAGER_80429C94) as usize;
    if platform::read_i32(manager + 0x1C) < 2 {
        fn_80051b40(player, W18_STEP_4_928, probe.as_ptr());
    } else {
        fn_80051b40(player, W18_STEP_5_128, probe.as_ptr());
    }
