// ---------------------------------------------------------------------------
// 0x80051930 - landing reaction dispatcher
// ---------------------------------------------------------------------------

/// Dispatches the landing reaction for the current `+0x3F0` state.
///
/// When `+0x3F0` is set and the effect probe `0x801690E0(107.0, ...)` and the
/// owning actor both succeed, the owning actor's `+0xE0` slot decides between
/// the sound path (`0x800CEA70`) and the actor-spawn path (`0x800E24B0` with
/// event `8` or `9`).
///
/// # Original
/// - Ghidra: `FUN_80051930` at `0x80051930` (352 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80051930_FUN_80051930.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May call `0x80195380`, `0x800CEA70`, `0x800E24B0` and [`fn_80051aa0`].
///
/// # Safety
/// `player + 0xDE8` and the owner lookup `0x8005F900` must be valid.
///
/// # Confidence
/// high - the event ids and the `+0x1090` branch were read from `main.elf`.
pub unsafe fn fn_80051930(player: usize) {
    if platform::read_u32(player + 0x3F0) != 0 {
        let effect = platform::read_u32(platform::read_u32(player + ACTOR_SUB) as usize + 4) as usize;
        // observed 0x80051958: `f1 = 107.0`, `r3 = effect + 0x28`.
        let probe: extern "C" fn(u32, f32) -> u32 =
            core::mem::transmute(0x8016_90E0usize);
        if probe((effect + 0x28) as u32, W18_ONE_HUNDRED_SEVEN) != 0 {
            let index = read_i8(player + ACTOR_OWNER);
            let owner = platform::call1(0x8005_F900, index as i32 as u32) as usize;
            if owner != 0 {
                if call_actor_slot1(owner, 0xE0) == 0 {
                    let flags = platform::read_u32(W18_FLAGS_80429F80);
                    if flags & 0x10 != 0 && flags & 0x40 != 0 {
                        if platform::read_u32(player + 0x430) == 0 {
                            platform::call3(
                                0x8019_5380,
                                platform::read_u32(W18_UI_8042A488),
                                0x252,
                                1,
                            );
                        }
                        let stage_index = platform::read_i32(player + 0x434) as usize;
                        platform::call3(
                            0x800C_EA70,
                            platform::read_u32(W18_SOUND_80429FB0),
                            index as i32 as u32,
                            platform::read_u32(W18_STAGE_TABLE_802EEB50 + stage_index * 4),
                        );
                    }
                } else if platform::read_u32(player + 0x3F0).wrapping_sub(2) < 2 {
                    let event = if platform::read_u32(owner + 0x1090) == 0 {
                        8
                    } else {
                        9
                    };
                    platform::call4(
                        0x800E_24B0,
                        platform::read_u32(W18_ACTOR_MANAGER_8042A050),
                        event,
                        index as i32 as u32,
                        1,
                    );
                }
            }
        }
    }

    if call_actor_slot(player, 0x284, 0) != 0 {
        fn_80051aa0(player, 1, 0);
    }
}

// ---------------------------------------------------------------------------
// 0x80051BD0 - gravity/velocity integration and ground snap
// ---------------------------------------------------------------------------

/// Advances the vertical motion by one frame and snaps to the stored ground
/// position when the player is falling and flag bit `0` is set.
///
/// If `+0x44C` is non-zero, the horizontal position is moved toward `+0x440`
/// in `+0x44C` equal steps. The vertical velocity gains `-0.28`, is clamped at
/// `-4.0`, and is integrated into `+0xB0`.
///
/// # Original
/// - Ghidra: `FUN_80051BD0` at `0x80051BD0` (224 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80051bd0_FUN_80051bd0.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// `1` when the player teleported to `+0x440..+0x448`, `0` otherwise.
///
/// # Side effects
/// Writes `+0xAC`, `+0xEC`, `+0x114`, `+0xB0` and `+0x44C`.
///
/// # Safety
/// The position fields must be writable floats.
///
/// # Confidence
/// high - `-0.28`, the `-4.0` clamp edge and the strict `vy < 0.0` teleport
/// were read from `main.elf`.
pub unsafe fn fn_80051bd0(player: usize) -> u32 {
    let count = platform::read_i32(player + 0x44C);
    if count != 0 {
        let target = read_f32(player + 0x440);
        let current = read_f32(player + ACTOR_POS);
        let step = (target - current) / count as f32;
        call_move_f32(player + ACTOR_POS, target, step);
        platform::write_i32(player + 0x44C, count - 1);
    }

    let gravity = W18_GRAVITY;
    let velocity = read_f32(player + 0xEC) + gravity;
    platform::write_f32(player + 0x114, gravity);
    platform::write_f32(player + 0xEC, velocity);
    if velocity < W18_NEG_FOUR {
        platform::write_f32(player + 0xEC, W18_NEG_FOUR);
    }

    let y = read_f32(player + 0xB0) + read_f32(player + 0xEC);
    platform::write_f32(player + 0xB0, y);

    if read_f32(player + 0xEC) < W18_ZERO
        && platform::read_u32(player + ACTOR_FLAGS) & 0x0000_0001 != 0
    {
        platform::write_f32(player + ACTOR_POS, read_f32(player + 0x440));
        platform::write_f32(player + 0xB0, read_f32(player + 0x444));
        platform::write_f32(player + 0xB4, read_f32(player + 0x448));
        1
    } else {
        0
    }
}

