// ---------------------------------------------------------------------------
// Local helpers
// ---------------------------------------------------------------------------

/// Returns the effect interface object mounted at `[[player + 0xDE8] + 4]`.
///
/// Every effect call in this section uses that object and its virtual `+0x5C`
/// three-float method.
unsafe fn w22_effect_interface(player: usize) -> usize {
    platform::read_u32(platform::read_u32(player + ACTOR_SUB) as usize + 4) as usize
}

/// Calls `0x800728C0`, the ground query used by [`fn_80049c70`].
///
/// The original takes `(anim_controller, xyz_in, height_out)` and returns
/// non-zero when the query found ground. The Ghidra C prints a `void` return,
/// but the caller tests `r3`.
unsafe fn w22_ground_query(anim: usize, position: *const f32, out: *mut f32) -> u32 {
    let function: extern "C" fn(u32, u32, u32) -> u32 =
        core::mem::transmute(0x8007_28C0usize);
    function(anim as u32, position as u32, out as u32)
}

// ---------------------------------------------------------------------------
// 0x80048C70 - per-frame action effects and state-selected sounds
// ---------------------------------------------------------------------------

/// Runs the player's per-frame action-effect block.
///
/// When `+0x1008` is clear and the two "busy" bits (`0x18000000`) of `+0x10D4`
/// are clear, it asks the actor's `+0xE8` slot for a scale byte and forwards it
/// to the landing-smoke dispatcher [`fn_8004cb30`]. It then starts one sound
/// selected by the current action state (`+0x111C`) and terrain type
/// (`+0x1090`): `0x153` for state 5, `0x107` for terrain 3, `0x106` for state
/// 7/11 and `0x105` for the remaining accepted states.
///
/// # Original
/// - Ghidra: `FUN_80048C70` at `0x80048C70` (256 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80048c70_FUN_80048c70.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May call [`fn_8004cb30`] and `0x80057E70` (sound/event starter); reads
/// `+0x1008`, `+0x10D4`, `+0x111C` and `+0x1090`.
///
/// # Safety
/// `player` and `player + 0x60` (class vtable) must be valid.
///
/// # Confidence
/// high - the state/terrain compare tree and both call targets were checked
/// in `main.elf`; the sound ids are observed, their names are not.
pub unsafe fn fn_80048c70(player: usize) {
    if platform::read_u32(player + 0x1008) != 0 {
        return;
    }

    if platform::read_u32(player + ACTOR_FLAGS) & 0x1800_0000 == 0 {
        let scale = call_actor_slot(player, 0xE8, 0xFFFF_FFFF) as u8;
        fn_8004cb30(player, scale as u32);
    }

    if platform::read_i32(player + ACTOR_STATE) == 5 {
        platform::call3(0x8005_7E70, player as u32, 0x153, 0);
    }

    if platform::read_i32(player + ACTOR_STAGE) == 3 {
        platform::call3(0x8005_7E70, player as u32, 0x107, 0);
        return;
    }

    let state = platform::read_i32(player + ACTOR_STATE);
    if (state < 0 || state > 6) && (state < 8 || state > 10) {
        if state == 7 || state == 0x0B {
            platform::call3(0x8005_7E70, player as u32, 0x106, 0);
            return;
        }
        if state != 0x0C {
            return;
        }
    }
    platform::call3(0x8005_7E70, player as u32, 0x105, 0);
}

// ---------------------------------------------------------------------------
// 0x80048EB0 - clear the two landing flags and start the drop sound
// ---------------------------------------------------------------------------

/// Clears event flags `0x7F`/`0x7A`, then starts sound `0x43C` when the
/// actor's `+0xE0` slot reports a hit.
///
/// # Original
/// - Ghidra: `FUN_80048EB0` at `0x80048EB0` (124 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80048eb0_FUN_80048eb0.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls actor slots `+0x3A4` and `+0xE0`, clears two event flags, and may
/// call `0x80057E70(player, 0x43C, 0)`.
///
/// # Safety
/// `player + 0x60` must hold a live vtable.
///
/// # Confidence
/// high - the `beq` on the `+0xE0` result and both flag ids are direct.
pub unsafe fn fn_80048eb0(player: usize) {
    let _ = call_actor_slot1(player, 0x3A4);
    fn_80056c70(player, 0x7F);
    fn_80056c70(player, 0x7A);

    if call_actor_slot1(player, 0xE0) != 0 {
        platform::call3(0x8005_7E70, player as u32, 0x43C, 0);
    }
}

// ---------------------------------------------------------------------------
// 0x80048F30 - attack pose 1 (effect 0x11)
// ---------------------------------------------------------------------------

/// Selects attack pose `1`, starts effect `0x11`, and clears the vertical
/// speed.
///
/// # Original
/// - Ghidra: `FUN_80048F30` at `0x80048F30` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80048f30_FUN_80048f30.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x14A4 = 1`, `+0x14A8 = 5`, `+0xEC = 0`; calls virtual `+0x5C`
/// on the effect interface with `(0x80370E98, 0x80370E9C, 0, 0x11)`.
///
/// # Safety
/// `[[player + 0xDE8] + 4]` must be a live effect interface.
///
/// # Confidence
/// high - pose/state stores and the effect vector were checked in `main.elf`.
pub unsafe fn fn_80048f30(player: usize) {
    platform::write_u32(player + W22_ATTACK_POSE, 1);
    let iface = w22_effect_interface(player);
    let _ = call_interface_slot_f32x3(
        iface,
        0x5C,
        read_f32(W22_EFFECT_80370E98),
        read_f32(W22_EFFECT_80370E9C),
        W22_ZERO,
        0x11,
    );
    platform::write_u32(player + W22_ACTION_STATE, 5);
    write_f32(player + 0xEC, W22_ZERO);
}

// ---------------------------------------------------------------------------
// 0x80048FA0 - attack pose 2
// ---------------------------------------------------------------------------

/// Selects attack pose `2`, copies the model's first word into `+0x114`, and
/// starts the pose's vertical rate (`-2.0` for pose source 1, otherwise
/// `-6.0`).
///
/// # Original
/// - Ghidra: `FUN_80048FA0` at `0x80048FA0` (152 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80048fa0_FUN_80048fa0.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x14A4`, `+0x11C`, `+0x110`, `+0x114`, `+0x118`, `+0xEC`,
/// `+0x14A8`; sets event flag `0x1C`; calls [`fn_80048e10`].
///
/// # Safety
/// `player + 0x60` must hold a live vtable with a `+0x3C4` slot returning a
/// readable pointer.
///
/// # Confidence
/// high - the model pointer call and the `+0x14A0` branch were re-read from
/// the instruction stream.
pub unsafe fn fn_80048fa0(player: usize) {
    platform::write_u32(player + W22_ATTACK_POSE, 2);
    write_f32(player + ACTOR_ANIM_RATE, W22_TENTH);
    write_f32(player + ACTOR_SPEED_TARGET, W22_ZERO);

    let model = call_actor_slot1(player, 0x3C4) as usize;
    platform::write_u32(player + 0x114, platform::read_u32(model));
    write_f32(player + 0x118, W22_NEG_SIX);

    if platform::read_i32(player + 0x14A0) == 1 {
        write_f32(player + 0xEC, W22_NEG_TWO);
    } else {
        write_f32(player + 0xEC, W22_NEG_SIX);
    }

    fn_80056c70(player, 0x1C);
    fn_80048e10(player);
    platform::write_u32(player + W22_ACTION_STATE, 5);
}

