pub unsafe fn fn_80049050(player: usize) {
    platform::write_u32(player + W22_ACTION_STATE, 0x14);
    platform::write_u32(player + W22_ATTACK_POSE, 4);

    let iface = w22_effect_interface(player);
    let _ = call_interface_slot_f32x3(
        iface,
        0x5C,
        read_f32(W22_EFFECT_80370EA4),
        read_f32(W22_EFFECT_80370EA8),
        W22_ZERO,
        0x12,
    );

    fn_80056c70(player, 0x1E);
    fn_80056cb0(player, 0x1C);
    fn_80056c70(player, 0x9F);

    let model = call_actor_slot1(player, 0x3C4) as usize;
    platform::write_u32(player + 0x114, platform::read_u32(model));
    write_f32(player + 0x118, W22_NEG_SIX);
    write_f32(player + 0xEC, W22_ZERO);
}

