// ---------------------------------------------------------------------------
// 0x80049540 - choose the air/ground action branch
// ---------------------------------------------------------------------------

/// Chooses the player's air/ground action branch for the current motion and
/// world query state.
///
/// The function first restarts effect `0x12` unless the sub-object's `+0x154`
/// word is already `0x12`. It then splits on bit 0 of `+0x10D4`:
/// * clear: if the movement state at `+0xEA4` reports "active", select attack
///   pose [`fn_80048fa0`];
/// * set: when the sub-object's `+0x28` query is clear, either start the
///   vertical pose [`fn_8004b460`] plus slot `+0x398`, or call slot `+0x448`;
///   otherwise it either starts [`fn_80049110`] or [`fn_80049180`] after
///   updating the `+0x6D8` latch and the `+0x14A8` action state.
///
/// # Original
/// - Ghidra: `FUN_80049540` at `0x80049540` (400 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80049540_FUN_80049540.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x10C`, `+0x14A8`, `+0x6D8`; may set/clear flags `0xAE`; starts
/// effect `0x12`; calls [`fn_8004b1c0`], [`fn_8004b460`], [`fn_80048e10`],
/// [`fn_80048fa0`], [`fn_80049110`] and [`fn_80049180`].
///
/// # Safety
/// The actor vtable, the sub-object at `+0xDE8` and the effect interface must
/// be valid.
///
/// # Confidence
/// high - the branch tree and latch offsets were checked in `main.elf`. The
/// Ghidra `thunk_FUN_8005e500` is the one-instruction thunk at `0x8005E830`
/// (`b 0x8005E500`), so the Rust calls `0x8005E500` directly.
pub unsafe fn fn_80049540(player: usize) {
    let sub = platform::read_u32(player + ACTOR_SUB) as usize;
    let inner = platform::read_u32(sub + 4) as usize;

    if platform::read_u32(inner + 0x154) != 0x12 {
        let iface = w22_effect_interface(player);
        let _ = call_interface_slot_f32x3(
            iface,
            0x5C,
            read_f32(W22_EFFECT_80370EA4),
            read_f32(W22_EFFECT_80370EA8),
            W22_ZERO,
            0x12,
        );
    }

    if platform::read_u32(player + ACTOR_FLAGS) & 1 == 0 {
        // observed 0x800496A4: the thunk at 0x8005E830 jumps to 0x8005E500.
        if platform::call1(0x8005_E500, (player + ACTOR_MOVE_STATE) as u32) != 0 {
            fn_80048fa0(player);
        }
    } else if platform::call1(0x8016_9020, (inner + 0x28) as u32) == 0 {
        if fn_8004b1c0(player) == 0 {
            let _ = call_actor_slot1(player, 0x448);
        } else {
            let rate = fn_8004b460(player);
            write_f32(player + ACTOR_SPEED, rate);
            let _ = call_actor_slot1(player, 0x398);
        }
    } else if platform::call1(0x8005_E500, (player + ACTOR_MOVE_STATE) as u32) != 0 {
        // observed 0x800495C4: `bc 4,2` (`bne`) selects 0x80048E10 for a
        // non-zero query result.
        fn_80048e10(player);

        if platform::read_i32(player + 0x6D8) == 0 {
            if platform::read_u32(player + ACTOR_FLAGS2) & 0x0040_0000 != 0 {
                platform::write_u32(player + W22_ACTION_STATE, 0x0F);
            }
            if platform::read_u8(W22_MODE_8042A21F) != 0
                && platform::read_u32(player + ACTOR_FLAGS) & 1 != 0
                && platform::read_u32(player + ACTOR_FLAGS2) & 2 == 0
            {
                platform::write_u32(player + 0x6D8, 1);
            }
        }

        if platform::read_u32(player + W22_ACTION_STATE) == 0 {
            fn_80056cb0(player, 0xAE);
            fn_80049180(player);
        }
    } else {
        fn_80056cb0(player, 0xAE);
        fn_80049110(player);
    }
}

