// ---------------------------------------------------------------------------
// 0x80051590 - the nine-state motion/attack state machine
// ---------------------------------------------------------------------------

/// Runs the player's `+0x3F4` motion state machine.
///
/// The nine states cover: starting the `0x56` effect when the target query
/// succeeds (0); waiting for the target to be below the player before entering
/// the `-1.9` fall (1); clamping the fall to `+0x438` and starting `0x57` (2);
/// waiting for flag `0x69` before running the landing helper (3); running
/// gravity and starting `0x59` (4); starting `0x8F` and a five-frame timer
/// (5); waiting for that timer (6); waiting for manager bit `0x08` (7); and
/// finally handing control to `0x80051AA0` (8).
///
/// # Original
/// - Ghidra: `FUN_80051590` at `0x80051590` (772 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80051590_FUN_80051590.c`
///
/// # Arguments
/// - `player`: gameplay player object; `+0x3F4` is the state byte.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x3F4`, `+0xB0`, `+0xEC`, `+0x145C`; sets/clears event flags
/// `0x66`..`0x6A`; starts effects `0x56`, `0x57`, `0x59`, `0x8F`; calls
/// [`fn_80051490`], [`fn_80051bd0`] and `0x80051AA0`.
///
/// # Safety
/// The player, manager `0x80429C94` and effect interface must be valid.
///
/// # Confidence
/// high - every switch case was read from `main.elf`. The case-1 target test
/// deliberately calls the flag helper on the *other* actor (the pointer
/// returned by `0x8005FB90`), not on `player`.
pub unsafe fn fn_80051590(player: usize) {
    match platform::read_u8(player + W22_MOTION_STATE) {
        0 => {
            let probe = platform::call3(
                0x8004_74E0,
                player as u32,
                (-0x4000i32) as u32,
                10,
            );
            let sub = platform::read_u32(player + ACTOR_SUB) as usize;
            let inner = platform::read_u32(sub + 4) as usize;
            if probe == 0 && platform::call1(0x8016_9020, (inner + 0x28) as u32) != 0 {
                platform::write_u8(player + W22_MOTION_STATE, 1);
                let iface = w22_effect_interface(player);
                let _ = call_interface_slot_f32x3(
                    iface,
                    0x5C,
                    read_f32(W22_EFFECT_803711D4),
                    read_f32(W22_EFFECT_803711D8),
                    W22_ZERO,
                    0x56,
                );
                fn_80056c70(player, 0x66);
            }
        }
        1 => {
            if fn_80056cf0(player, 0x67) == 0 {
                return;
            }

            let manager = platform::read_u32(MANAGER_80429C94) as usize;
            let owner = read_i8(player + ACTOR_OWNER) as i32 as u32;
            let slot = platform::call2(0x8005_B840, manager as u32, owner);

            let mut enter = slot == 0xFFFF_FFFF;
            if !enter {
                let target = call0_u32(0x8005_FB90);
                if target == 0 {
                    enter = true;
                } else {
                    let target = target as usize;
                    let limit = read_f32(target + 0xB0)
                        + W22_SEVEN_TENTHS * read_f32(target + 0x1030);
                    // observed 0x80051690: `bc 12,1` is `bgt`, so the
                    // state-2 body is entered when the target limit is below
                    // the player Y.
                    if limit < read_f32(player + 0xB0) {
                        enter = true;
                    } else if fn_80056cf0(target, 0x68) != 0 {
                        enter = true;
                    }
                }
            }

            if enter {
                platform::write_u8(player + W22_MOTION_STATE, 2);
                fn_80056cb0(player, 0x66);
                let manager = platform::read_u32(MANAGER_80429C94) as usize;
                platform::write_u32(
                    manager + 0x10,
                    platform::read_u32(manager + 0x10) | 1,
                );
                write_f32(player + 0xEC, W22_NEG_ONE_POINT_NINE);
            }
        }
        2 => {
            let y = read_f32(player + 0xB0) + read_f32(player + 0xEC);
            write_f32(player + 0xB0, y);
            let ground = read_f32(player + 0x438);
            // observed 0x800516E8: `fcmpo f1,f0` + `bc 4,0` (`bge`) returns
            // when the new Y is at or above the ground; clamp only below it.
            if y < ground {
                write_f32(player + 0xB0, ground);
                fn_80056c70(player, 0x68);
                write_f32(player + 0xEC, W22_ZERO);
                platform::write_u8(player + W22_MOTION_STATE, 3);
                let iface = w22_effect_interface(player);
                let _ = call_interface_slot_f32x3(
                    iface,
                    0x5C,
                    read_f32(W22_EFFECT_803711E0),
                    read_f32(W22_EFFECT_803711E4),
                    W22_ZERO,
                    0x57,
                );
            }
        }
        3 => {
            if fn_80056cf0(player, 0x69) != 0 {
                fn_80051490(player);
            }
        }
        4 => {
            if fn_80051bd0(player) != 0 {
                platform::write_u8(player + W22_MOTION_STATE, 5);
                let iface = w22_effect_interface(player);
                let _ = call_interface_slot_f32x3(
                    iface,
                    0x5C,
                    read_f32(W22_EFFECT_803711F8),
                    read_f32(W22_EFFECT_803711FC),
                    W22_ZERO,
                    0x59,
                );
                let _ = call_actor_slot1(player, 0x414);
            }
        }
        5 => {
            let sub = platform::read_u32(player + ACTOR_SUB) as usize;
            let inner = platform::read_u32(sub + 4) as usize;
            if platform::call1(0x8016_9020, (inner + 0x28) as u32) != 0 {
                let iface = w22_effect_interface(player);
                let _ = call_interface_slot_f32x3(
                    iface,
                    0x5C,
                    read_f32(W22_EFFECT_80371480),
                    read_f32(W22_EFFECT_80371484),
                    W22_ZERO,
                    0x8F,
                );
                platform::write_u8(player + W22_MOTION_STATE, 6);
                platform::write_u32(player + W22_TIMER_145C, 5);
            }
        }
        6 => {
            if platform::read_u32(player + W22_TIMER_145C) == 0 {
                fn_80056c70(player, 0x6A);
                platform::write_u8(player + W22_MOTION_STATE, 7);
            }
        }
        7 => {
            let manager = platform::read_u32(MANAGER_80429C94) as usize;
            let probe = platform::call3(0x8004_74E0, player as u32, 0, 10);
            if platform::read_u32(manager + 0x10) & 8 != 0 && probe == 0 {
                platform::write_u32(player + W22_TIMER_145C, 7);
                platform::write_u8(player + W22_MOTION_STATE, 8);
            }
        }
        8 => {
            if platform::read_u32(player + W22_TIMER_145C) == 0 {
                fn_80051aa0(player, 1, 0);
            }
        }
        _ => {}
    }
}

// ---------------------------------------------------------------------------
// 0x80053120 - damage gate and terrain/hand-state input handling
// ---------------------------------------------------------------------------

/// Runs the player's damage gate and the per-frame terrain/hand-state input
/// handling.
///
/// The gate is open only when the global enable byte `0x8042A21F` is set and
/// no "damage mode 4" is active. It reads the frame/actor array at
/// `0x80429F50` to decide whether an enemy target is present, then either
/// clears the 180-frame damage timer (target present) or advances it. With
/// damage mode 6 active it starts the reset helper when a target is present,
/// or, when no target is present and flag `0x45` is clear, samples the
/// controller bits and updates the terrain byte `+0x348` and the five
/// hand-state timers at `+0x46C`.
///
/// # Original
/// - Ghidra: `FUN_80053120` at `0x80053120` (700 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80053120_FUN_80053120.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x348`, `+0x46C`..`+0x47C`, `+0x480`; sets/clears flag `0x75`;
/// calls [`fn_8004db40`], [`fn_80052420`], [`fn_80051ef0`], the controller
/// mask query `0x8006A200`, and the movement-state setters `0x8005E910`,
/// `0x8005E930`, `0x8005E960`, `0x8005E980`.
///
/// # Safety
/// `0x80429F50`, `0x80429E00` and the selected frame entry must be readable;
/// negative owner indices are not expected.
///
/// # Confidence
/// high - the branch order, the 180-frame limit, the controller masks and the
/// scene-X comparison were checked against `main.elf`.
pub unsafe fn fn_80053120(player: usize) {
    fn_80056cb0(player, 0x75);

    if platform::read_u8(W22_MODE_8042A21F) == 0 || fn_8004db40(player, 4) != 0 {
        return;
    }

    let array = platform::read_u32(W22_FRAME_ARRAY_80429F50) as usize;
    let index = read_i8(player + ACTOR_OWNER) as i32;
    let entry_address =
        (array as i32).wrapping_add(4).wrapping_add(index.wrapping_mul(4)) as usize;
    let entry = platform::read_u32(entry_address) as usize;

    let has_target =
        platform::read_u32(entry + 0x14) != 0 || platform::read_u8(entry + 0x8C) != 0;

    if fn_8004db40(player, 6) == 0 {
        if has_target {
            platform::write_u32(player + 0x480, 0);
        } else {
            let frames = platform::read_u32(player + 0x480).wrapping_add(1);
            platform::write_u32(player + 0x480, frames);
            if frames >= 0xB4 {
                fn_80052420(player);
                platform::write_u32(player + 0x480, 0);
            }
        }
    } else if has_target {
        // observed 0x800531FC: the call site also loads r4 = 0, but the
        // callee ignores every argument after the player.
        fn_80051ef0(player);
    } else if fn_80056cf0(player, 0x45) == 0 {
        fn_80056c70(player, 0x75);

        if platform::call1(0x8006_A200, 2) != 0 {
            platform::write_u8(player + 0x348, 0);
        } else if platform::call1(0x8006_A200, 4) != 0 {
            platform::write_u8(player + 0x348, 1);
        } else if platform::call1(0x8006_A200, 8) != 0 {
            platform::call2(0x8005_E910, (player + ACTOR_MOVE_STATE) as u32, 1);
            platform::write_u32(player + 0x474, 6);
        } else if platform::call1(0x8006_A200, 0x10) != 0 {
            platform::call2(0x8005_E960, (player + ACTOR_MOVE_STATE) as u32, 0x100);
            platform::call2(0x8005_E910, (player + ACTOR_MOVE_STATE) as u32, 0x100);
            platform::write_u32(player + 0x478, 5);
        } else if platform::call1(0x8006_A200, 0x20) != 0 {
            platform::call2(0x8005_E960, (player + ACTOR_MOVE_STATE) as u32, 0x100);
            platform::call2(0x8005_E910, (player + ACTOR_MOVE_STATE) as u32, 0x100);
            platform::write_u32(player + 0x47C, 0x1E);
        } else if platform::call1(0x8006_A200, 0x40) != 0 {
            platform::call1(0x8005_E980, (player + ACTOR_MOVE_STATE) as u32);
        } else if platform::call1(0x8006_A200, 0x80) != 0 {
            let scene = platform::read_u32(W22_SCENE_80429E00) as usize;
            // observed 0x80053348: `bc 4,1` (`ble`) selects 1 when the
            // scene threshold is at or below the player X.
            let on_high_ground = read_f32(scene + 0x48) <= read_f32(player + ACTOR_POS);
            platform::write_u8(player + 0x348, on_high_ground as u8);
        }

        // observed 0x80053368: five consecutive timer words, one per hand.
        let mut index = 0u32;
        while index < 5 {
            let address = player + 0x46C + (index as usize) * 4;
            let timer = platform::read_u32(address);
            if timer != 0 {
                let next = timer - 1;
                platform::write_u32(address, next);
                if next == 0 {
                    // observed 0x80053380: `bc 4,1` (`ble`) selects 0x100 for
                    // timers 3 and 4; timer 2 selects 1.
                    if index.wrapping_sub(3) < 2 {
                        platform::call2(
                            0x8005_E930,
                            (player + ACTOR_MOVE_STATE) as u32,
                            0x100,
                        );
                    } else if index == 2 {
                        platform::call2(0x8005_E930, (player + ACTOR_MOVE_STATE) as u32, 1);
                    }
                }
            }
            index += 1;
        }
    } else {
        for offset in [0x46Cu32, 0x470, 0x474, 0x478, 0x47C] {
            platform::write_u32(player + offset as usize, 0);
        }
    }
}

// ---------------------------------------------------------------------------
// 0x800533E0 - damage-mode gate
// ---------------------------------------------------------------------------

/// Commits the damage interface when event flag `0x60` is set and the
/// "riding/held" exception does not apply.
///
/// The exception requires all of: bit 1 of `+0x10D8`, a live `+0x244`
/// object, a live first-word object, and the short `0x1D4` at that object's
/// `+8`. When the exception applies the function returns `0` without side
/// effects; otherwise it starts the damage interface with selector `0` (if
/// damage mode 4 is clear) and zeroes both horizontal speeds.
///
/// # Original
/// - Ghidra: `FUN_800533E0` at `0x800533E0` (176 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800533e0_FUN_800533e0.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// `1` when the damage path ran, `0` when it was suppressed.
///
/// # Side effects
/// May call [`fn_8004e290`] with `0x80354BEC` and selector `0`; writes
/// `+0xEC = 0`, `+0x10C = 0`.
///
/// # Safety
/// `+0x244` and its first-word object must be valid when the flags advertise
/// them.
///
/// # Confidence
/// high - the four-part exception condition and both zero stores were checked
/// against `main.elf`.
pub unsafe fn fn_800533e0(player: usize) -> u32 {
    if fn_80056cf0(player, 0x60) == 0 {
        return 0;
    }

    let flags2 = platform::read_u32(player + ACTOR_FLAGS2);
    if flags2 & 2 != 0 {
        let holder = platform::read_u32(player + 0x244) as usize;
        if holder != 0 {
            let object = platform::read_u32(holder) as usize;
            if object != 0 && platform::read_u16(object + 8) == 0x1D4 {
                return 0;
            }
        }
    }

    if fn_8004db40(player, 4) == 0 {
        fn_8004e290(player, IFACE_80354BEC, 0);
    }

    write_f32(player + 0xEC, W22_ZERO);
    write_f32(player + ACTOR_SPEED, W22_ZERO);
    1
}

// ---------------------------------------------------------------------------
// 0x80053540 - reset the five model-effect records
// ---------------------------------------------------------------------------

/// Resets the five 0x100-byte model-effect records at `+0x148`, `+0x1164`,
/// `+0x1208`, `+0x12AC` and `+0x1350`.
///
/// Each record is first released through `0x8008C380`. The first two then
/// receive mode `0x1FF` and coordinate mask `0xFFBEFFFE`; the last three
/// receive mode `0xBD` and mask `0`, and their `+0x2D` byte is cleared.
///
/// # Original
/// - Ghidra: `FUN_80053540` at `0x80053540` (188 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80053540_FUN_80053540.c`
///
/// # Arguments
/// - `player`: gameplay player object.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Five calls to `0x8008C380`; writes the `+0x30`, `+0x2D` and `+0x34`
/// fields of each record.
///
/// # Safety
/// The five records must be readable/writable; `0x8008C380` walks their
/// linked-list words.
///
/// # Confidence
/// medium - all offsets and constants are exact; the gameplay name of the
/// records is inferred from their repeated layout.
pub unsafe fn fn_80053540(player: usize) {
    platform::call1(0x8008_C380, (player + W22_EFFECT_SLOT_0) as u32);
    platform::write_u32(player + W22_EFFECT_SLOT_0 + 0x30, 0x1FF);
    platform::write_u8(player + W22_EFFECT_SLOT_0 + 0x2D, 0);
    platform::write_u32(player + W22_EFFECT_SLOT_0 + 0x34, 0xFFBE_FFFE);

    platform::call1(0x8008_C380, (player + W22_EFFECT_SLOT_1) as u32);
    platform::write_u32(player + W22_EFFECT_SLOT_1 + 0x30, 0x1FF);
    platform::write_u8(player + W22_EFFECT_SLOT_1 + 0x2D, 0);
    platform::write_u32(player + W22_EFFECT_SLOT_1 + 0x34, 0xFFBE_FFFE);

    platform::call1(0x8008_C380, (player + W22_EFFECT_SLOT_2) as u32);
    platform::write_u32(player + W22_EFFECT_SLOT_2 + 0x30, 0xBD);
    platform::write_u8(player + W22_EFFECT_SLOT_2 + 0x2D, 0);
    platform::write_u32(player + W22_EFFECT_SLOT_2 + 0x34, 0);

    platform::call1(0x8008_C380, (player + W22_EFFECT_SLOT_3) as u32);
    platform::write_u32(player + W22_EFFECT_SLOT_3 + 0x30, 0xBD);
    platform::write_u8(player + W22_EFFECT_SLOT_3 + 0x2D, 0);
    platform::write_u32(player + W22_EFFECT_SLOT_3 + 0x34, 0);

    platform::call1(0x8008_C380, (player + W22_EFFECT_SLOT_4) as u32);
    platform::write_u32(player + W22_EFFECT_SLOT_4 + 0x30, 0xBD);
    platform::write_u8(player + W22_EFFECT_SLOT_4 + 0x2D, 0);
    platform::write_u32(player + W22_EFFECT_SLOT_4 + 0x34, 0);
}

// ---------------------------------------------------------------------------
// 0x80053650 - copy the player transform into two effect records
// ---------------------------------------------------------------------------

/// Copies the player's four-word transform at `+0x164..+0x170` into effect
/// records 1 and 2, and derives their mode words from `+0x178`.
///
/// Record 2 (`+0x12C8`) receives the transform, the caller's byte at
/// `+0x12D9`, and `+0x12DC = [+0x178] + 7`. Record 1 (`+0x1224`) receives the
/// same transform and byte, and `+0x1238 = [+0x178] & ~7`.
///
/// # Original
/// - Ghidra: `FUN_80053650` at `0x80053650` (80 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80053650_FUN_80053650.c`
///
/// # Arguments
/// - `player`: gameplay player object.
/// - `mode`: byte stored at both record `+0x2D`/`+0x2D` positions
///   (`+0x12D9` and `+0x1235`).
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes 12 words/bytes in the two effect records.
///
/// # Safety
/// `player` must be writable through `+0x1238`.
///
/// # Confidence
/// high - the byte stream stores `[+0x178] + 7`, while the Ghidra C prints a
/// constant `7`; the Rust follows the instruction (`addi r5, r0, 7` after
/// loading `+0x178`).
pub unsafe fn fn_80053650(player: usize, mode: u8) {
    let value = platform::read_u32(player + 0x178);

    platform::write_u32(player + 0x12C8, platform::read_u32(player + 0x164));
    platform::write_u32(player + 0x12CC, platform::read_u32(player + 0x168));
    platform::write_u32(player + 0x12D0, platform::read_u32(player + 0x16C));
    platform::write_u32(player + 0x12D4, platform::read_u32(player + 0x170));
    platform::write_u8(player + 0x12D9, mode);
    platform::write_u32(player + 0x12DC, value.wrapping_add(7));

    platform::write_u32(player + 0x1224, platform::read_u32(player + 0x164));
    platform::write_u32(player + 0x1228, platform::read_u32(player + 0x168));
    platform::write_u32(player + 0x122C, platform::read_u32(player + 0x16C));
    platform::write_u32(player + 0x1230, platform::read_u32(player + 0x170));
    platform::write_u8(player + 0x1235, mode);
    platform::write_u32(player + 0x1238, value & 0xFFFF_FFF8);
}

