// ===========================================================================
// Wave 39 constants (0x800534B0..0x8005D090) - effect-record binders,
// history shift registers, movement-bit stubs and slot-array leaves.
// ===========================================================================

/// `0x8008C3E0` - `(record, player, word)` effect-record binder. The five
/// calls in [`fn_800534b0`] hit exactly the five record slots (`+0x148`,
/// `+0x1164`, `+0x1208`, `+0x12AC`, `+0x1350`) that [`fn_80053650`] copies
/// the transform into. `// unknown:` gameplay role beyond the call shape.
const EFFECT_RECORD_BIND: usize = 0x8008_C3E0;

/// `0x8008C2C0` - one-argument reset for one effect record, called by
/// [`fn_80053600`] on the same five slots as [`EFFECT_RECORD_BIND`].
const EFFECT_RECORD_RESET: usize = 0x8008_C2C0;

/// `0x8008C330` - one-argument stop for one effect record, called by
/// [`fn_800537b0`] on the records whose mode byte is non-zero.
const EFFECT_RECORD_STOP: usize = 0x8008_C330;

/// `0x8015F480` - the `(f64, f64, ptr)` range helper behind
/// `thunk_FUN_8015F480` in [`fn_800540f0`]. `// unknown:` exact gameplay role.
const RANGE_F64_CALL: usize = 0x8015_F480;

/// `0x802EEB60` / `0x802EEB70` - the two `f32` tables read pairwise by
/// [`fn_800540f0`] with `index = (count - 1) * 4` in the `+0x394 == 3` state.
/// `// observed:` first entries re-read from `work/dol/main.elf`.
const RANGE_LO_TABLE_802EEB60: usize = 0x802E_EB60;
const RANGE_HI_TABLE_802EEB70: usize = 0x802E_EB70;

/// `0x802EEB80` - the `f32` scale table read by [`fn_800552d0`] with the low
/// byte of the slot `+0xE8` result. `// observed:` starts `4.0`, `8.0`, `16.0`.
const SCALE_TABLE_802EEB80: usize = 0x802E_EB80;

/// `0x80065FC0` - `// unknown:` predicate called by [`fn_80054ef0`] with the
/// entry word and `0`.
const ENTRY_PREDICATE: usize = 0x8006_5FC0;

/// `0x8042BAE8` - flag-mask `u32` table at `r2 - 0x7698` read by
/// [`fn_800557e0`]. `// observed:` entries re-read from `work/dol/main.elf`.
const FLAG_MASK_TABLE_8042BAE8: usize = 0x8042_BAE8;

/// Calls the `(f64, f64, ptr)` helper at `addr` and returns its `u32` result.
/// The two floats are the PowerPC `f1`/`f2` (or `f2`/`f3`) doubles.
///
/// # Safety
/// `addr` must point to a function with this exact ABI.
unsafe fn call_f64_u32(addr: usize, a: f64, b: f64, c: u32) -> u32 {
    let function: extern "C" fn(f64, f64, u32) -> u32 = core::mem::transmute(addr);
    function(a, b, c)
}

// ---------------------------------------------------------------------------
// 0x800534B0 - bind two words into the five effect records
// ---------------------------------------------------------------------------

/// Binds word `p2` into effect records `+0x148` and `+0x1164`, and word `p3`
/// into records `+0x1208`, `+0x12AC` and `+0x1350`, each with the player.
