    let owner = platform::read_u8(player + 0x38F);
    platform::write_u8(player + 0x12A7, state);
    platform::write_u8(player + 0x13EF, state);
    platform::write_u8(player + 0x1E8, owner);
    platform::write_u8(player + 0x12A8, owner);
    platform::write_u8(player + 0x13F0, owner);

    if fn_80056cf0(player, 0x74) != 0 {
        platform::write_u16(player + 0x180, platform::read_u16(player + 0x180) | 1);
    } else {
        platform::write_u16(player + 0x180, platform::read_u16(player + 0x180) & 0xFFFE);
    }

