/// `player + 0xDEC` - embedded interface object whose first word is its vtable
/// pointer. All four dispatch wrappers below call through this receiver.
const INTERFACE_0DEC: usize = 0x0DEC;

/// `0x8019A6D0` - effect spawner with an `f64` position in `f1`, the interface
/// object in `r3` and the effect id in `r4`. Shape shared with
/// `src/game/worldmap.rs`; `// inferred:` from the Ghidra prototype.
const SPAWN_8019A6D0: usize = 0x8019_A6D0;

/// `0x802B9280` - shared deallocator used across the sound and player code.
const DEALLOC_802B9280: usize = 0x802B_9280;

/// `0x8005DC80` - `(entry)` clear of one 12-byte track entry. `// unknown:` the
/// body reads a constant through `r2` and is not translated here; the call shape
/// is exact.
const TRACK_CLEAR_8005DC80: usize = 0x8005_DC80;

/// `0x8005DDC0` - `(entry, 0)` constructor for the track table. `// unknown:`
/// the body contains paired-single code; the two-argument call is exact.
const TRACK_CONSTRUCT_8005DDC0: usize = 0x8005_DDC0;

/// `0x802F1364` - base of the `0x24`-byte records copied into each 12-byte
/// track entry by [`fn_8005dca0`]. Only the first two words are read.
const TRACK_RECORD_TABLE_802F1364: usize = 0x802F_1364;

/// Stride of one track entry (`+0x00` byte, `+0x04`/`+0x08` two words).
const TRACK_ENTRY_STRIDE: usize = 0x0C;

/// Stride of one record in the `0x802F1364` table.
const TRACK_RECORD_STRIDE: usize = 0x24;

/// Number of entries in the track table (`0x84C / 0xC`).
const TRACK_ENTRY_COUNT: u32 = 0xB1;

/// Byte span cleared and re-seeded by [`fn_8005dcd0`].
const TRACK_TABLE_SPAN: usize = 0x84C;

/// Calls `(f64, u32, u32, u32)` and ignores the result.
///
/// # Safety
/// `addr` must point to a function with this exact EABI prototype.
unsafe fn call_f64_u32_u32_u32(addr: usize, value: f64, a: u32, b: u32, c: u32) {
    let function: extern "C" fn(f64, u32, u32, u32) = core::mem::transmute(addr);
    function(value, a, b, c);
}

/// Calls `vtable[slot]` on an interface object with two extra arguments.
///
/// # Safety
/// `object` must start with a vtable pointer and `slot` must name a method
/// taking `(object, arg1, arg2)`.
unsafe fn call_interface_slot2(object: usize, slot: usize, arg1: u32, arg2: u32) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let method = platform::read_u32(vtable + slot) as usize;
    platform::call3(method, object as u32, arg1, arg2)
}

/// Calls `vtable[slot]` on an interface object with three extra arguments.
///
/// # Safety
/// `object` must start with a vtable pointer and `slot` must name a method
/// taking `(object, arg1, arg2, arg3)`.
unsafe fn call_interface_slot3(
    object: usize,
    slot: usize,
    arg1: u32,
    arg2: u32,
    arg3: u32,
) -> u32 {
    let vtable = platform::read_u32(object) as usize;
    let method = platform::read_u32(vtable + slot) as usize;
    platform::call4(method, object as u32, arg1, arg2, arg3)
}

