// ---------------------------------------------------------------------------
// 0x8005ECE0 - clear the id tables and per-character arrays
// ---------------------------------------------------------------------------

/// Clears both four-entry id tables and the per-character counters/aux words of
/// the four characters named by [`W88_SLOT_CHAR_ID_80354E60`].
///
/// # Original
/// - Ghidra: `FUN_8005ECE0` at `0x8005ECE0` (164 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8005ece0_FUN_8005ece0.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Sets `0x80354E90[id] = 5` and `0x80354EA0[id] = 0` for ids `0..2`, clears the
/// eight words of `0x80354E10`/`0x80354E20`, repeats the counter/aux clear for
/// id `3`, and clears `0x80429CC0`. Ids are read before any store, so a table
/// holding duplicate ids is cleared twice, as in the export.
///
/// # Safety
/// All cited BSS/SDA words must be writable.
///
/// # Confidence
/// high - the four ids, the `5` initial value, the eight clears and the final
/// store are literal.
pub unsafe fn fn_8005ece0() {
    let id0 = platform::read_u32(W88_SLOT_CHAR_ID_80354E60) as usize;
    let id1 = platform::read_u32(W88_SLOT_CHAR_ID_80354E60 + 4) as usize;
    let id2 = platform::read_u32(W88_SLOT_CHAR_ID_80354E60 + 8) as usize;
    let id3 = platform::read_u32(W88_SLOT_CHAR_ID_80354E60 + 0xC) as usize;

    platform::write_u32(W88_CHAR_COUNTER_80354E90 + id0 * 4, 5);
    platform::write_u32(W88_CHAR_AUX_80354EA0 + id0 * 4, 0);
    platform::write_u32(W88_CHAR_COUNTER_80354E90 + id1 * 4, 5);
    platform::write_u32(W88_CHAR_AUX_80354EA0 + id1 * 4, 0);
    platform::write_u32(W88_CHAR_COUNTER_80354E90 + id2 * 4, 5);
    platform::write_u32(W88_CHAR_AUX_80354EA0 + id2 * 4, 0);

    let mut slot = 0usize;
    while slot < 4 {
        platform::write_u32(W88_SLOT_TABLE_A_80354E10 + slot * 4, 0);
        slot += 1;
    }
    let mut slot = 0usize;
    while slot < 4 {
        platform::write_u32(W88_SLOT_TABLE_B_80354E20 + slot * 4, 0);
        slot += 1;
    }

    platform::write_u32(W88_CHAR_COUNTER_80354E90 + id3 * 4, 5);
    platform::write_u32(W88_CHAR_AUX_80354EA0 + id3 * 4, 0);

    platform::write_u32(W88_WORD_80429CC0, 0);
}

