// ---------------------------------------------------------------------------
// Wave-92 call helpers
//
// Three call shapes in this bucket return or take `f64` in `f1` and cannot go
// through `platform::call*`, which is integer-only.
// ---------------------------------------------------------------------------

/// Calls `0x80045A10`, the fireball builder:
/// `(value: f64, index: f64, this, a, 0, c, d)`.
///
/// # Safety
/// `0x80045A10` must still be the seven-argument builder; the object must be
/// live.
unsafe fn w92_call_fireball_build(
    value: f64,
    index: f64,
    this: usize,
    a: u32,
    c: u32,
    d: u32,
) {
    let function: extern "C" fn(f64, f64, u32, u32, u32, u32, u32) =
        core::mem::transmute(W92_FIREBALL_BUILD_80045A10);
    function(value, index, this as u32, a, 0, c, d);
}

/// Calls an `(f64, u32, u32)` entry point and discards the result.
///
/// # Safety
/// `addr` must be an entry point with that exact shape.
unsafe fn w92_call_f64_u32_u32(addr: usize, value: f64, a: u32, b: u32) -> u32 {
    let function: extern "C" fn(f64, u32, u32) -> u32 = core::mem::transmute(addr);
    function(value, a, b)
}

/// Calls an `(f64)` entry point on an interface object and discards the result.
///
/// # Safety
/// `addr` must be an entry point with that exact shape.
unsafe fn w92_call_f64(addr: usize, value: f64) {
    let function: extern "C" fn(f64) = core::mem::transmute(addr);
    function(value);
}

/// Calls a `(f64, f64, f64, u32, u32)` entry point and discards the result.
///
/// # Safety
/// `addr` must be an entry point with that exact shape; the last two
/// arguments are the object and the selector.
unsafe fn w92_call_f64_f64_f64(addr: usize, a: f64, b: f64, c: f64, object: u32, selector: u32) {
    let function: extern "C" fn(f64, f64, f64, u32, u32) = core::mem::transmute(addr);
    function(a, b, c, object, selector);
}

/// Reads an `f64` from a fixed SDA slot.
///
/// # Safety
/// `addr` must point at eight readable bytes holding a double.
unsafe fn w92_read_f64(addr: usize) -> f64 {
    let mut raw = [0u32; 2];
    platform::write_u32(raw.as_mut_ptr() as usize, platform::read_u32(addr));
    platform::write_u32(raw.as_mut_ptr() as usize + 4, platform::read_u32(addr + 4));
    f64::from_bits(((raw[0] as u64) << 32) | raw[1] as u64)
}

// ---------------------------------------------------------------------------
// 0x80040DE0 - two-stage hit test against a four-word box
// ---------------------------------------------------------------------------

/// Builds the four-word box `{a, a, b, b}` from the SDA and runs both hit
/// tests on the actor's `+0xAC` position; reports success when either is
/// non-zero.
///
/// The second test runs only when the first returns zero, exactly as the
/// original's `&&` comma expression does.
///
/// # Original
/// - Ghidra: `FUN_80040DE0` at `0x80040DE0` (144 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80040de0_FUN_80040de0.c`
///
/// # Arguments
/// - `this`: the fireball actor. `+0xAC` is its position, `+0x349` the owner
///   byte both tests take as their fourth argument.
///
/// # Returns
/// `1` when either test hit, `0` when both returned zero.
///
/// # Side effects
/// Calls `0x800B56E0` and possibly `0x80064DA0`. Nothing is written.
///
/// # Safety
/// `this + 0xAC` must be a readable three-float position and `this + 0x349`
/// readable; `0x802EE868` must stay a valid descriptor.
///
/// # Confidence
/// medium - the guards and both calls are literal; the two callees and the box
/// descriptor are known only by address, so their roles stay inferred.
pub unsafe fn fn_80040de0(this: usize) -> u32 {
    // observed: the box is {a, a, b, b} - two SDA words replicated in pairs.
    let a = platform::read_u32(W92_HIT_BOX_WORD_A_8042B734);
    let b = platform::read_u32(W92_HIT_BOX_WORD_B_8042B738);
    let mut hit_box = [0u32; 4];
    let box_addr = hit_box.as_mut_ptr() as usize;
    platform::write_u32(box_addr, a);
    platform::write_u32(box_addr + 4, a);
    platform::write_u32(box_addr + 8, b);
    platform::write_u32(box_addr + 12, b);

    let owner = platform::read_u8(this + 0x349) as u32;
    let first = platform::call4(
        W92_HIT_TEST_800B56E0,
        (this + 0xAC) as u32,
        W92_HIT_DESC_802EE868 as u32,
        box_addr as u32,
        owner,
    );
    if first != 0 {
        return 1;
    }
    let second = platform::call4(
        W92_HIT_VERIFY_80064DA0,
        this as u32,
        (this + 0xAC) as u32,
        W92_HIT_DESC_802EE868 as u32,
        owner,
    );
    if second != 0 {
        1
    } else {
        0
    }
}

// ---------------------------------------------------------------------------
// 0x80040E70 - bind the animation controller and the `+0x2DC` workspace
// ---------------------------------------------------------------------------

/// Binds the animation controller at `+0x1EC` to the actor and points the
/// working record at `+0x23C` to the scratch block at `+0x2DC`.
///
/// # Original
/// - Ghidra: `FUN_80040E70` at `0x80040E70` (80 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80040e70_FUN_80040e70.c`
///
/// # Arguments
/// - `this`: the fireball actor being initialised.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// `0x8006D090(this + 0x1EC, this, a, b, c)` and the `+0x23C` self-pointer.
///
/// # Safety
/// `this` must be writable through `+0x23C` and the controller at `+0x1EC`
/// must be the freshly constructed one.
///
/// # Confidence
/// medium - the five-argument bind and the self-pointer store are literal; the
/// three descriptors are known only by address.
pub unsafe fn fn_80040e70(this: usize) {
    platform::call5(
        W92_ANIM_BIND_8006D090,
        (this + 0x1EC) as u32,
        this as u32,
        W92_ANIM_DESC_802EE840 as u32,
        W92_ANIM_DESC_802EE84C as u32,
        W92_ANIM_DESC_802EE858 as u32,
    );
    platform::write_u32(this + 0x23C, (this + 0x2DC) as u32);
}

