                    let matched = if low == 3 && high == 2 {
                        let handle = platform::call2(
                            0x800E_0380,
                            platform::read_u32(W98_CUE_OWNER_8042A040),
                            0xFFFF_FFFF,
                        );
                        if platform::read_u32(this + 0x14) == 0 {
                            platform::call4(0x800C_E3C0, handle, 2, 3, 0x90) == 0
                        } else {
                            platform::call4(0x800C_E3C0, handle, 2, 3, 0x120) == 0
                        }
                    } else {
                        platform::call2(0x800F_AE40, high, low) == 0
                    };
                    if matched {
                        let ui = platform::read_u32(W98_CELEBRATE_8042A1F0) as usize;
                        platform::write_u8(ui + 0xB9, 0);
                        platform::write_u8(ui + 0xB8, 1);
                        platform::write_u8(ui + 0xB5, 1);
                        platform::write_u32(this + 0x08, 3);
                        awarded = true;
                    }
