///
/// # Side effects
/// Four writes: the presence byte, the handle table, the per-character flags and
/// the SDA handle word.
///
/// # Safety
/// `slot < 4` and the character id must index the four-entry flag table.
///
/// # Confidence
/// high - the four stores and the `8` flag are literal; only the flag's meaning
/// is inferred.
pub unsafe fn fn_8005f570(handle: u32, slot: u32) {
    let character = platform::read_u32(W88_SLOT_CHAR_ID_80354E60 + slot as usize * 4);
    let mask = platform::read_u8(SDA_SLOT_MASK_80429CA8) | (1u8 << (slot & 0xFF));
    platform::write_u8(SDA_SLOT_MASK_80429CA8, mask);
    platform::write_u32(W88_SLOT_HANDLES_80354E50 + slot as usize * 4, 1);
    platform::write_u32(W88_CHAR_FLAGS_80354E80 + character as usize * 4, 8);
    platform::write_u32(W98_HANDLE_WORD_80429CC4, handle);
}

// ---------------------------------------------------------------------------
// 0x8005FDB0 - reserve a slot and start its actor
// ---------------------------------------------------------------------------

/// Reserves `slot` when it is free: sets the presence bit, asks the slot's actor
/// for vtable slot `+0xE0`, and calls [`fn_8005feb0`] (the "reserve" counter)
/// when the actor is missing or the predicate returned zero.
///
/// # Original
/// - Ghidra: `FUN_8005FDB0` at `0x8005FDB0` (116 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8005fdb0_FUN_8005fdb0.c`
///
/// # Arguments
/// - `slot`: `0..=3`. The export drops the argument of the inner `0x8005F900`
///   call; the same slot is passed, as the surrounding mask test requires.
///
/// # Returns
/// `1` when the slot was free and is now reserved, `0` when it was already
/// taken.
///
/// # Side effects
/// One presence-bit write, one slot resolve and at most one counter call.
///
/// # Safety
/// The slot tables must be live, and a present slot must resolve to an actor
/// with a class vtable when the predicate runs.
///
/// # Confidence
/// medium - the mask test, the bit write and the two calls are literal; the
/// dropped argument of `0x8005F900` is supplied as `slot`.
pub unsafe fn fn_8005fdb0(slot: u32) -> u32 {
    let bit = 1u32 << (slot & 0xFF);
    if u32::from(platform::read_u8(SDA_SLOT_MASK_80429CA8)) & bit != 0 {
        return 0;
    }
    let mask = platform::read_u8(SDA_SLOT_MASK_80429CA8) | bit as u8;
    platform::write_u8(SDA_SLOT_MASK_80429CA8, mask);

    let actor = fn_8005f900(slot as usize);
    let ready = actor != 0 && call_actor_slot1(actor as usize, 0xE0) != 0;
    if !ready {
        fn_8005feb0();
    }
    1
}

// ---------------------------------------------------------------------------
// 0x8005FE30 - release a slot and drop its actor
// ---------------------------------------------------------------------------

/// Releases `slot` when it is present: clears the presence bit, asks the actor
/// for vtable slot `+0xE0`, calls [`fn_8005fed0`] (the "release" counter) when
/// the actor is missing or the predicate returned zero, and then runs
/// [`fn_8005f920`].
///
/// # Original
/// - Ghidra: `FUN_8005FE30` at `0x8005FE30` (124 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8005fe30_FUN_8005fe30.c`
///
/// # Arguments
/// - `slot`: `0..=3`; the inner `0x8005F900` argument is dropped by the export
///   and is supplied as `slot`.
///
/// # Returns
/// `1` when the slot was present, `0` otherwise.
///
/// # Side effects
/// One presence-bit write, one slot resolve, at most one counter call and one
/// [`fn_8005f920`] call.
///
/// # Safety
/// Same requirements as [`fn_8005fdb0`].
///
/// # Confidence
/// medium - the polarity, the two calls and the tail call are literal; the
/// dropped argument is supplied as `slot`.
pub unsafe fn fn_8005fe30(slot: u32) -> u32 {
    let bit = 1u32 << (slot & 0xFF);
    if u32::from(platform::read_u8(SDA_SLOT_MASK_80429CA8)) & bit == 0 {
        return 0;
    }
    let mask = platform::read_u8(SDA_SLOT_MASK_80429CA8) & !(bit as u8);
    platform::write_u8(SDA_SLOT_MASK_80429CA8, mask);

    let actor = fn_8005f900(slot as usize);
    let ready = actor != 0 && call_actor_slot1(actor as usize, 0xE0) != 0;
    if !ready {
        fn_8005fed0();
    }
    fn_8005f920();
    1
}

// ===========================================================================
// Wave 103: the remaining `0x80050000` bucket leaves.
//
// Three groups, all on the same gameplay player actor:
//
// * the per-frame motion integrator (`0x80054F80`, `0x80055330`, `0x80055900`,
//   `0x80055FF0`, `0x80056E40`, `0x800571C0`, `0x800573F0`) - velocity, ground
//   and edge probes, and the two rotated-offset builders;
// * the effect-slot inserter pair `0x80058B20` / `0x80058EE0`, which share the
//   `0x802DCD74` save-register prologue and the `+0x74` slot array;
// * the HUD/spawn bookkeeping leaves `0x8005BFD0..0x8005F5C0`.
//
// Start at [`fn_80055330`] for the ground probe or [`fn_8005f5c0`] for the
// per-frame slot update.
// ===========================================================================

