/// Calls the four-argument ground probe `0x80075FD0`.
///
/// # Safety
/// `addr` must be that entry point; both `f32` triples must be readable and the
/// out word writable.
unsafe fn w103_call_probe(
    addr: usize,
    a: usize,
    b: usize,
    out: usize,
    terrain: u32,
    flag: u32,
) -> u32 {
    let function: extern "C" fn(usize, usize, usize, u32, u32, u32) -> u32 =
        core::mem::transmute(addr);
    function(a, b, out, terrain, flag, 0)
}

/// Calls the `(f64, f64, u32, u32, u32) -> u32` water query `0x80076530`.
