/// the 1/256-turn argument the original builds from a 16-bit height angle.
///
/// # Safety
/// `addr` must be `0x80237BD0` or `0x80237C40`.
unsafe fn w103_sin_cos(addr: usize, angle_256: f32) -> f32 {
    let function: extern "C" fn(f64) -> f64 = core::mem::transmute(addr);
    function(angle_256 as f64) as f32
}

// ---------------------------------------------------------------------------
// 0x80054F80 - per-frame vertical-velocity and landing selection
// ---------------------------------------------------------------------------

/// Chooses the vertical velocity `+0xEC` and the per-frame motion `+0x10C4`
/// for one player frame.
///
/// In the airborne flag path (`+0x10D4 & 2`) the routine picks the jump
/// animation cue `0x272`, `0x273` or `0x281` from the `+0x10D8` bits and zeroes
/// the upward speed on the first frame above ground. In the grounded path
/// (`+0x10D4 & 1`) it copies the `+0x20C` velocity into `+0x10C4`, applies the
/// idle and slope rules, and finally builds the `+0x14C8` step from the value
/// at `+0x310`.
///
/// # Original
/// - Ghidra: `FUN_80054F80` at `0x80054F80` (820 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80054f80_FUN_80054f80.c`
///
/// # Arguments
/// - `player`: gameplay actor; position at `+0xAC`, vertical velocity at
///   `+0xEC`, state flags at `+0x10D4`/`+0x10D8`/`+0x10DC`/`+0x10E0`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0xEC`, `+0x10C`, `+0xAC`, `+0x10C4..+0x10CC`, `+0x14C8` and
/// `+0x106C`; calls the cue player `0x80057EE0`, the event setter
/// [`fn_80056c70`] and three actor/animation predicates.
///
/// # Safety
/// `player` must be a live actor with the class vtable at `+0x60` and the
/// animation controller at `+0x1EC`.
///
/// # Confidence
/// medium - every branch, mask and store is literal; the `+0x310`/`+0x1090`
/// field roles are inferred from this single use, and `0x80070760` /
/// `0x80070820` are called by address because their return types are not
/// declared in the export.
pub unsafe fn fn_80054f80(player: usize) {
    let flags = platform::read_u32(player + 0x10D4);

    if flags & 2 != 0 {
        let moving = read_f32(player + 0xEC) > W87_ZERO_8042B878
            || fn_80056cf0(player, 0x4E) != 0;
        if moving && platform::read_u32(player + 0x10DC) & 2 == 0 {
            let state = platform::read_u32(player + 0x10D8);
            if state & 0x0200_0000 == 0 && state & 0x8000_0000 == 0 && state & 4 == 0 {
                // inferred: the `+0x1090 == 3` flavour selects the longer cue.
                let alternate = if platform::read_i32(player + 0x1090) == 3 {
                    1
                } else {
                    0
                };
                if state & 0x0020_0000 == 0 {
                    if state & 0x0100_0000 == 0 {
                        fn_80057ee0(player, 0x272, alternate, 0);
                    } else if state & 0x0400_0000 == 0 {
                        fn_80057ee0(player, 0x281, alternate, 0);
                    } else {
                        fn_80057ee0(player, 0x272, alternate, 0);
                    }
                } else {
                    fn_80057ee0(player, 0x273, alternate, 0);
                }
            }
        }
        if read_f32(player + 0xEC) > W87_ZERO_8042B878 {
            write_f32(player + 0xEC, W87_ZERO_8042B878);
            platform::write_u32(player + 0x106C, 0);
            fn_80056c70(player, 0xBF);
        }
    }

    if platform::read_u32(player + 0x10D4) & 1 != 0 {
        let flags = platform::read_u32(player + 0x10D4);
        if flags & 0xC000_0000 != 0 {
            let x = platform::read_u32(player + 0x20C);
            let y = platform::read_u32(player + 0x210);
            let z = platform::read_u32(player + 0x214);
            platform::write_u32(player + 0x10C4, x);
            platform::write_u32(player + 0x10C8, y);
            platform::write_u32(player + 0x10CC, z);
        }
        if flags & 0x4000 == 0 && platform::read_u32(player + 0x10D8) & 4 == 0 {
            if flags & 0x0800_0000 == 0 {
                // observed: `0x8004B1A0` and event `0x30` both fail -> -2.0.
                if fn_8004b1a0(player) == 0 && fn_80056cf0(player, 0x30) == 0 {
                    write_f32(player + 0xEC, W103_NEG_TWO_8042B8D8);
                } else {
                    write_f32(player + 0xEC, W87_ZERO_8042B878);
                }
            } else {
                write_f32(player + 0xEC, W87_ZERO_8042B878);
                let rate = call_actor_slot_f32_ret(player, 0x104);
                write_f32(player + 0x10C4, W87_ZERO_8042B878);
                write_f32(player + 0x10C8, read_f32(player + 0x210) * rate);
                write_f32(player + 0x10CC, W87_ZERO_8042B878);
            }
        } else {
            write_f32(player + 0xEC, W87_ZERO_8042B878);
        }
        if fn_80056cf0(player, 0x5F) != 0 {
            write_f32(player + 0x10C, W87_ZERO_8042B878);
        }
        if flags & 0x8000 != 0 && flags & 0x4000 == 0 {
            platform::write_i32(player + 0x111C, 5);
        }
        if platform::read_u32(player + 0x10D8) & 2 == 0
            && flags & 2 != 0
            && platform::call1(0x8007_0760, (player + 0x1EC) as u32) != 0
            && platform::call2(
                0x8007_0820,
                (player + 0x1EC) as u32,
                u32::from(platform::read_u8(player + 0x348)),
            ) == 1
        {
            // observed: facing byte picks the left/right land cue.
            if platform::read_u8(player + 0x348) == 0 {
                fn_80056c70(player, 0x1B);
            } else {
                fn_80056c70(player, 0x1A);
            }
            write_f32(player + 0x10C, W87_ZERO_8042B878);
            let x = platform::read_u32(player + 0xB8);
            platform::write_u32(player + 0xAC, x);
        }
    }

    if platform::read_u32(player + 0x10D4) & 1 == 0
        && platform::read_u32(player + 0x10D8) & 2 == 0
        && platform::read_u32(player + 0x10DC) & 1 != 0
        && platform::read_u32(player + 0x10E0) & 2 != 0
    {
        write_f32(player + 0x14C8, W87_ZERO_8042B878);
        let slope = read_f32(player + 0x310);
        if W103_CENTI_8042B9E0 <= read_f32(player + 0x10C).abs()
            && W87_ZERO_8042B878 < slope * read_f32(player + 0x10C)
        {
            write_f32(player + 0x14C8, slope);
            // observed: a value inside the unit interval steps backwards.
            let mut step = slope;
            if W103_CENTI_8042B9E0 < slope.abs() {
                step = W87_ONE_8042B874;
                if slope.abs() < W87_ONE_8042B874 && slope <= W87_ONE_8042B874 {
                    step = W103_NEG_ONE_8042B8A8;
                }
            }
            let x = read_f32(player + 0xAC) + step;
            write_f32(player + 0xAC, x);
        }
    }
}

// ---------------------------------------------------------------------------
// 0x80055330 - ground/water classification for one player frame
// ---------------------------------------------------------------------------

/// Classifies the ground under the player and stores the resulting state bits.
///
/// The scene's water level advances one frame into `+0x113C`, the current level
/// is written to `+0x1138`, and `0x80075270` classifies the point
/// `(+0xAC, +0xB0)`. Codes `0`/`2` are refined with the player's own height
/// from [`fn_800552d0`]; codes `3`/`4` arm `+0x114A` unless event `0x7E` is
/// set; code `2` records the water entry point; code `1` checks the surface
/// depth and stores the `0x80076530` result at `+0x1140`.
///
/// # Original
/// - Ghidra: `FUN_80055330` at `0x80055330` (512 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80055330_FUN_80055330.c`
///
/// # Arguments
/// - `player`: gameplay actor; water state lives at `+0x1138..+0x1158`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes `+0x1138`, `+0x113C`, `+0x1140`, `+0x114A`, `+0x114C..+0x1158` and
/// ORs bits into the `+0x10D4` flag word.
///
/// # Safety
/// `player` must be a live actor with the class vtable at `+0x60` and a readable
/// `+0x1EC` animation controller; the scene word at [`W22_SCENE_80429E00`] must
/// be live.
///
/// # Confidence
/// high - the classifier call, every mask and every store are literal; only the
/// `CONCAT44(0x43300000, v ^ 0x80000000)` conversion is reduced to `as f32`.
pub unsafe fn fn_80055330(player: usize) {
    platform::write_u8(player + 0x114A, 0);
    let previous = platform::read_u32(player + 0x1138);
    platform::write_u32(player + 0x113C, previous);

    let scene = platform::read_u32(W22_SCENE_80429E00) as usize;
    let water = platform::read_u32(scene + 0x8FE70);
    platform::write_u32(player + 0x1138, water);

    let x = read_f32(player + 0xAC);
    let y = read_f32(player + 0xB0);
    let terrain = u32::from(platform::read_u8(player + 0x38F));
    let mut kind = call_f64_u32(
        W103_GROUND_80075270,
        x as f64,
        y as f64,
        (player + 0x1138) as u32,
    ) & 0xFF;

    if kind != 0 && read_f32(player + 0xB0) <= read_f32(player + 0x1138) {
        let flags = platform::read_u32(player + 0x10D4);
        platform::write_u32(player + 0x10D4, flags | 0x8000);
        if kind == 2 {
            platform::write_u32(player + 0x10D4, flags | 0x4_8000);
        }
    }

    if kind == 0 || kind == 2 {
        let height = fn_800552d0(player);
        let code = call_f64_u32(
            W103_GROUND_80075270,
            x as f64,
            height as f64,
            (player + 0x1138) as u32,
        ) as u8;
        if code != 2 {
            return;
        }
        let flags = platform::read_u32(player + 0x10D4);
        platform::write_u32(player + 0x10D4, flags | 0x1_4000);
        kind = 2;
    }

    if kind.wrapping_sub(3) < 2 {
        if fn_80056cf0(player, 0x7E) == 0 {
            platform::write_u8(player + 0x114A, kind as u8);
        }
    } else if kind == 2 {
        let flags = platform::read_u32(player + 0x10D4);
        platform::write_u32(player + 0x10D4, flags | 0x4_0000);
        // observed: the export passes the address of a two-word local, the third
        // component is the actor's own `+0xB4`, and `0x80075780` yields a u16.
        let mut point = [0u32; 2];
        platform::call1(W103_GROUND_POINT_80075750, point.as_mut_ptr() as u32);
        platform::write_u32(player + 0x114C, point[0]);
        platform::write_u32(player + 0x1150, point[1]);
        platform::write_u32(player + 0x1154, platform::read_u32(player + 0xB4));
        let mut code = [0u16; 2];
        platform::call1(W103_GROUND_CODE_80075780, code.as_mut_ptr() as u32);
        platform::write_u16(player + 0x1158, code[0]);
    } else if kind == 1 {
        let height = fn_800552d0(player) as f64;
        if height <= read_f32(player + 0x1138) as f64 {
            let flags = platform::read_u32(player + 0x10D4);
            platform::write_u32(player + 0x10D4, flags | 0x4000);
        }
        let object = call_actor_slot1(player, 0xEC) as usize;
        // observed: signed `+0xC` word scaled by 4096.0.
        let depth = platform::read_i32(object + 0xC) as f32 / W103_FIXED_4096_8042B8B0;
        if read_f32(player + 0xB0) + depth <= read_f32(player + 0x1138) {
            let flags = platform::read_u32(player + 0x10D4);
            platform::write_u32(player + 0x10D4, flags | 0x1_0000);
        }
        let result = w103_call_f64_f64_u32_u32_u32(
            W103_WATER_80076530,
            read_f32(player + 0xAC) as f64,
            read_f32(player + 0x1138) as f64,
            terrain,
            u32::from(platform::read_u8(player + 0x1035)),
            0,
        );
        platform::write_u32(player + 0x1140, result);
    }
}

// ---------------------------------------------------------------------------
// 0x80055900 - install a target horizontal position through a slope step
// ---------------------------------------------------------------------------

/// Moves `+0xB0` toward the target slope height when the horizontal target
/// `+0xAC` changes.
///
/// The new target is compared with the stored `+0xAC`; when it differs, event
/// `0x7E` is clear and the 16-bit slope `0x80070920(this + 0x1EC, rising)`
/// returns a non-zero low half, the routine adds
/// `(target - old) * (sin / cos)` of that slope to `+0xB0`, then latches the
/// target into `+0xAC`.
///
/// # Original
/// - Ghidra: `FUN_80055900` at `0x80055900` (252 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80055900_FUN_80055900.c`
///
/// # Arguments
/// - `target`: requested horizontal position (the `f64` the export keeps in
///   `f1`).
/// - `this`: gameplay actor; `+0xAC` is the current horizontal target, `+0xB0`
///   the height and `+0x1EC` the animation controller.
///
/// # Returns
/// `1` when the target was latched, `0` when it was already current.
///
/// # Side effects
/// At most one `+0xB0` add and one `+0xAC` store.
///
/// # Safety
/// `this` must be a live actor and `+0x1EC` a valid animation controller.
///
/// # Confidence
/// medium - the equality test, the one-shot store and the `sin/cos` ratio are
/// literal; the GQR-scaled `psq_l` halfword conversion is reduced to
/// `angle * 1/256`, the scale the sibling bodies read from `0x8042B8C0`.
pub unsafe fn fn_80055900(target: f64, this: usize) -> u32 {
    let current = read_f32(this + 0xAC) as f64;
    if current == target {
        return 0;
    }
    let rising = current <= target;
    if fn_80056cf0(this, 0x7E) == 0 {
        let angle = platform::call2(
            W103_SLOPE_80070920,
            (this + 0x1EC) as u32,
            rising as u32,
        );
        if angle & 0xFFFF != 0 {
            let scaled = W103_ANGLE_SCALE_8042B8C0 * (angle as u16 as i16) as f32;
            let sin = w103_sin_cos(W103_SIN_80237BD0, scaled);
            let cos = w103_sin_cos(W103_COS_80237C40, scaled);
            let delta = (target - current) as f32;
            let height = read_f32(this + 0xB0) + delta * (sin / cos);
            write_f32(this + 0xB0, height);
        }
    }
    write_f32(this + 0xAC, target as f32);
    1
}

// ---------------------------------------------------------------------------
// 0x80055FF0 - depth and edge band enforcement
// ---------------------------------------------------------------------------

/// Keeps the player inside the walkable depth band and the scene's horizontal
/// edges.
///
/// The depth band is `+0x3C - 20.0` (or `- 64.0` in the two special stage modes)
/// measured from the scene's `+0x3C` surface and the clearance constants
/// `16.0` / `128.0`; the horizontal band is the `0x80082240` edge query widened
/// by a per-frame margin. Every violation clears the blocked-direction event
/// flags `0xB9`/`0xBA` (and `0xB6` when the actor's `+0xE0` predicate holds) and
/// asks the state machine slot `+0x11C` for the matching push (`3` up, `2`
/// left, `0` right).
///
/// # Original
/// - Ghidra: `FUN_80055FF0` at `0x80055FF0` (880 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80055ff0_FUN_80055ff0.c`
///
/// # Arguments
/// - `player`: gameplay actor; `+0xAC/+0xB0/+0xB4` is the position,
///   `+0x31C..+0x324` the collision extents and `+0x10C0` a 12-bit fixed-point
///   margin word.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Clears events through [`fn_80056c70`] and calls the actor vtable slots
/// `+0xE0` and `+0x11C`. No memory is written directly.
///
/// # Safety
/// `player` must be a live actor, the world object at [`W98_WORLD_80429DD0`] and
/// the scene at [`W22_SCENE_80429E00`] must be live.
///
/// # Confidence
/// medium - the comparisons, the constants (re-read from `work/dol/main.elf`)
/// and the call order are literal; the `+0x31C`/`+0x324` pair is inferred as
/// the collision extents because only their signs are used here.
pub unsafe fn fn_80055ff0(player: usize) {
    let world = platform::read_u32(W98_WORLD_80429DD0) as usize;
    let scene = platform::read_u32(W22_SCENE_80429E00) as usize;
    let mode = platform::read_u32(W18_MODE_80429CA0);
    let stage = platform::read_u8(world + 0x90079);

    let mut limit = W103_TWENTY_8042B958;
    if mode > 1 || stage == 1 || stage == 3 {
        limit = W103_SIXTY_FOUR_8042B9FC;
    }

    let surface = read_f32(scene + 0x3C);
    let inner = surface - read_f32(scene + 0x44);
    let top = read_f32(player + 0xB0) + read_f32(player + 0x324) + read_f32(player + 0x31C);

    if top < inner - W103_SIXTEEN_8042B87C {
        fn_80056c70(player, 0xB9);
        fn_80056c70(player, 0xBA);
        if call_actor_slot1(player, 0xE0) != 0 {
            fn_80056c70(player, 0xB6);
        }
    }
    if top < inner - limit {
        call_actor_slot(player, 0x11C, 3);
    }

    let split = read_f32(player + 0xB0) + read_f32(player + 0x324) - read_f32(player + 0x31C);
    if W103_SIXTEEN_8042B87C + surface < split {
        fn_80056c70(player, 0xB9);
    }
    if call_actor_slot1(player, 0xE0) != 0
        && W103_HUNDRED_TWENTY_EIGHT_8042B9E4 + surface < split
    {
        fn_80056c70(player, 0xB6);
    }

    if fn_80056cf0(player, 0x81) == 0 {
        let mut margin = W87_ZERO_8042B878;
        if fn_80056cf0(player, 0xB8) == 0 {
            let flag = platform::read_u8(world + 0x900C6);
            if flag == 0 || platform::read_u8(world + 0x900FE) == 4 {
                if mode > 1 {
                    margin = W103_SIXTEEN_8042B87C;
                }
            } else {
                // observed: `(fixed12 / 4096.0 - 1.0) + +0x318`, negated.
                let fixed = platform::read_i32(player + 0x10C0) as f32
                    / W103_FIXED_4096_8042B8B0
                    - W87_ONE_8042B874;
                margin = -(fixed + read_f32(player + 0x318));
            }
        }

        let base = w98_call_f64_owner(
            0x8008_2240,
            read_f32(player + 0xAC) as f64,
            scene as u32,
        );
        let left = (base - margin as f64) as f32;
        let x_high = read_f32(player + 0xAC)
            + read_f32(player + 0x320)
            + read_f32(player + 0x318);
        if x_high < (base - W103_SIXTEEN_8042B87C as f64) as f32 {
            fn_80056c70(player, 0xB9);
            fn_80056c70(player, 0xBA);
            if call_actor_slot1(player, 0xE0) != 0 {
                fn_80056c70(player, 0xB6);
            }
        }
        if x_high < left {
            call_actor_slot(player, 0x11C, 2);
        }

        let right_edge = (base + read_f32(scene + 0x40) as f64) as f32;
        let x_low = (read_f32(player + 0xAC) + read_f32(player + 0x320))
            - read_f32(player + 0x318);
        let right = (margin as f64 + right_edge as f64) as f32;
        if W103_SIXTEEN_8042B87C + right_edge < x_low {
            fn_80056c70(player, 0xB9);
            fn_80056c70(player, 0xBA);
            if call_actor_slot1(player, 0xE0) != 0 {
                fn_80056c70(player, 0xB6);
            }
        }
        if right < x_low {
            call_actor_slot(player, 0x11C, 0);
        }
    }
}

// ---------------------------------------------------------------------------
// 0x80056620 - multi-hit acceptance predicate
// ---------------------------------------------------------------------------

/// Decides whether the current hit request may start another hit chain.
///
/// Four independent gates set bits in the accepted-mask word at `+0x3B4`:
/// the two "already in the corner" flag pairs, the area/level triple
/// `+0x120C..+0x120E` on the world object, the two sub-object comparators
/// [`fn_800565a0`] / [`fn_800565e0`], and the actor's `+0x118` probe. Event
/// `0x3C` blocks the last two gates.
///
/// # Original
/// - Ghidra: `FUN_80056620` at `0x80056620` (720 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80056620_FUN_80056620.c`
///
/// # Arguments
/// - `player`: gameplay actor; `+0x3B0` is the requested-hit bits and `+0x3B4`
///   the accepted-hit bits, `+0x10D4` the state flags.
///
/// # Returns
/// `1` when the hit is accepted (and `+0x3B4` has been updated), `0` otherwise.
///
/// # Side effects
/// ORs bits into `+0x3B4` and calls the actor vtable slot `+0x118` up to four
/// times.
///
/// # Safety
/// `player` must be a live actor with the class vtable at `+0x60`, and the
/// world object at [`PLAYER_ARRAY_8042A1C8`] must be live.
///
/// # Confidence
/// medium - every mask, comparison and bit store is literal; the `+0x3B0` /
/// `+0x3B4` pair is read as "requested / accepted" from the only two uses in
/// this file, and the `0x800565A0`/`0x800565E0` roles follow their wave-49
/// docs.
pub unsafe fn fn_80056620(player: usize) -> u32 {
    let state = platform::read_u32(player + 0x10D4);
    if (state & 0x0008_0000 != 0 && state & 0x40 != 0)
        || (state & 0x0010_0000 != 0 && state & 0x20 != 0)
    {
        return 1;
    }

    let world = platform::read_u32(PLAYER_ARRAY_8042A1C8) as usize;
    if platform::read_u8(world + 0x120C) == 5
        && platform::read_u8(world + 0x120D) == 0x17
        && platform::read_u8(world + 0x120E) == 1
        && W103_NEG_1420_8042BA00 <= read_f32(player + 0xB0)
        && call_actor_slot3(player, 0x118, 0xB, 1) != 0
    {
        platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 8);
        return 1;
    }

    let request = platform::read_u32(player + 0x3B0);
    if request & 0x20A != 0 && request & 0x414 != 0 && fn_800565a0(player) != 0 {
        if request & 0x18 != 0 && call_actor_slot3(player, 0x118, 0xB, 1) != 0 {
            if request & 8 != 0 {
                platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 8);
            }
            if request & 0x10 != 0 {
                platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 0x10);
            }
            return 1;
        }
        if request & 6 != 0 && call_actor_slot3(player, 0x118, 1, 1) != 0 {
            if request & 2 != 0 {
                platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 2);
            }
            if request & 4 != 0 {
                platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 4);
            }
            return 1;
        }
    }

    if fn_80056cf0(player, 0x3C) != 0 {
        return 0;
    }

    let request = platform::read_u32(player + 0x3B0);
    if request & 0x1140 != 0 && request & 0x8A0 != 0 && fn_800565e0(player) != 0 {
        if request & 0x60 != 0 && call_actor_slot3(player, 0x118, 0xB, 0) != 0 {
            if request & 0x20 != 0 {
                platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 0x20);
            }
            if request & 0x40 != 0 {
                platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 0x40);
            }
            return 1;
        }
        if request & 0x180 != 0 && call_actor_slot3(player, 0x118, 1, 0) != 0 {
            if request & 0x80 != 0 {
                platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 0x80);
            }
            if request & 0x100 != 0 {
                platform::write_u32(player + 0x3B4, platform::read_u32(player + 0x3B4) | 0x100);
            }
            return 1;
        }
    }
    0
}

// ---------------------------------------------------------------------------
// 0x80056E40 - horizontal speed integration
// ---------------------------------------------------------------------------

/// Advances the player's horizontal velocity and position for one frame.
///
/// [`fn_80053ad0`] reports whether the actor touched ground this frame; when it
/// did, the `+0x110` animation rate is clamped to `[-0.5, 0.5]` and the `+0x10C`
/// velocity is stepped through `0x8015F480` with the `1.8` / `1.0` multiplier
/// selected by the current speed. The routine then clamps `+0x10C` (already
/// including the `+0x14C0` impulse) to `+/-5.0`, probes the two-point ground
/// segment at `(x + step, y + height*0.5, z)`, folds the `+0x14C4`/`+0x14CC`
/// impulses into the motion accumulator, applies the `+0x10C4..+0x10CC` delta to
/// the position, and finally hands the resulting offset vector to
/// [`fn_800573f0`].
///
/// # Original
/// - Ghidra: `FUN_80056E40` at `0x80056E40` (888 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80056e40_FUN_80056e40.c`
///
/// # Arguments
/// - `player`: gameplay actor; position at `+0xAC`, vertical velocity at
///   `+0xEC`, horizontal velocity at `+0x10C`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Writes the velocity, position and animation-rate fields listed above and
/// calls `0x8015F480`, [`fn_8004c780`], [`fn_8004d350`], `0x80075FD0` and
/// [`fn_800573f0`].
///
/// # Safety
/// `player` must be a live actor with the animation controller at `+0x1EC` and
/// the class vtable at `+0x60`.
///
/// # Confidence
/// medium - the clamps, the call order and every store are literal; the
/// two-point probe's role is inferred from its `y + half*0.5` height, and the
/// `+0x14C4`/`+0x14CC` pair is read as "pending impulse" from how it is
/// consumed here.
pub unsafe fn fn_80056e40(player: usize) {
    let mut amount = W87_ZERO_8042B878;
    let anchored = fn_80053ad0(player, &mut amount as *mut f32) != 0;

    let mut speed = read_f32(player + 0x110);
    if fn_80056cf0(player, 0xAC) != 0 {
        let mut index = fn_80057cc0(player).wrapping_sub(1) as i32;
        if index < 0 {
            index = 0;
        }
        if index > 4 {
            index = 4;
        }
        speed = read_f32(player + 0x110) * read_f32(W103_RATE_TABLE_802EEB8C + index as usize * 4);
    }

    let mut step = W87_ONE_8042B874;
    if anchored {
        if speed < W103_NEG_HALF_8042BA04 {
            speed = W103_NEG_HALF_8042BA04;
        }
        if W103_HALF_8042B8C4 < speed {
            speed = W103_HALF_8042B8C4;
        }
        // observed: a current velocity inside the speed limit gets the longer
        // step, otherwise the unit step.
        if read_f32(player + 0x10C).abs() <= speed.abs() {
            step = W103_ONE_POINT_EIGHT_8042BA08;
        }
    }

    let target = (read_f32(player + 0x11C) as f64 * step as f64) as f32 as f64;
    call_f64_u32(
        RANGE_F64_CALL,
        speed as f64,
        target,
        (player + 0x10C) as u32,
    );
    fn_8004c780(player);

    let mut limit = W103_FIVE_8042B900;
    if fn_80056cf0(player, 0x88) != 0 && W103_FIVE_8042B900 < speed.abs() {
        limit = speed.abs();
    }
    let sum = read_f32(player + 0x10C) + read_f32(player + 0x14C0);
    let clamped = if sum < -limit {
        -limit
    } else if limit < sum {
        limit
    } else {
        sum
    };
    write_f32(player + 0xE8, clamped);

    if W87_ZERO_8042B878 <= clamped * amount {
        let height = read_f32(player + 0xB0) + read_f32(player + 0x1030) * W103_HALF_8042B8C4;
        let near = [
            amount + (read_f32(player + 0xAC) + clamped),
            height,
            read_f32(player + 0xB4),
        ];
        let far = [amount + (near[0] + clamped), height, near[2]];
        let mut out = [0u32; 1];
        let hit = w103_call_probe(
            W103_PROBE_80075FD0,
            near.as_ptr() as usize,
            far.as_ptr() as usize,
            out.as_mut_ptr() as usize,
            u32::from(platform::read_u8(player + 0x38F)),
            u32::from(platform::read_u8(player + 0x1035)),
        );
        if hit != 0 {
            amount = W87_ZERO_8042B878;
        }
    }

    let mut accum = amount;
    let impulse = read_f32(player + 0x14C4);
    if impulse != W87_ZERO_8042B878 {
        if platform::read_u32(player + 0x10D4) & 1 == 0 {
            accum += impulse;
        } else {
            if impulse * read_f32(player + 0x10C) < W87_ZERO_8042B878 {
                let v = read_f32(player + 0x10C) + impulse;
                write_f32(player + 0x10C, v);
            }
            write_f32(player + 0x14C4, W87_ZERO_8042B878);
        }
    }

    let drag = read_f32(player + 0x14CC);
    if drag != W87_ZERO_8042B878 {
        if platform::read_u32(player + 0x10D4) & 1 == 0 {
            accum += drag;
            call_f64_u32(
                RANGE_F64_CALL,
                W87_ZERO_8042B878 as f64,
                read_f32(player + 0x14D0) as f64,
                (player + 0x14CC) as u32,
            );
        } else {
            write_f32(player + 0x14CC, W87_ZERO_8042B878);
        }
    }

    if platform::read_u32(player + 0x10D4) & 1 != 0 && fn_80056cf0(player, 0x5F) != 0 {
        write_f32(player + 0x10C, W87_ZERO_8042B878);
    }
    let horizontal = read_f32(player + 0x10C);
    write_f32(player + 0x1050, horizontal);

    let mut floor = read_f32(player + 0x118);
    if platform::read_u32(player + 0x10D4) & 0x1800_0000 != 0 {
        floor = W87_ZERO_8042B878;
    }
    fn_8004d350(player);

    let dx = read_f32(player + 0x10C4);
    let dy = read_f32(player + 0x10C8);
    let dz = read_f32(player + 0x10CC);
    write_f32(player + 0xAC, read_f32(player + 0xAC) + dx);
    write_f32(player + 0xB0, read_f32(player + 0xB0) + dy);
    write_f32(player + 0xB4, read_f32(player + 0xB4) + dz);
    write_f32(player + 0x1054, read_f32(player + 0xEC));

    let mut vertical = read_f32(player + 0xEC) + read_f32(player + 0x114);
    if vertical < floor {
        vertical = floor;
    }
    write_f32(player + 0xEC, vertical);

    let offset = [read_f32(player + 0xE8) + accum, vertical, read_f32(player + 0xF0)];
    fn_800573f0(player, offset.as_ptr() as usize);
}

// ---------------------------------------------------------------------------
// 0x800571C0 - rotated offset from a slope and a facing scale
// ---------------------------------------------------------------------------

/// Builds the rotated horizontal offset of a speed vector and hands it to
/// `0x8006CD00`.
///
/// When the state has the "rising" bit (`+0x10D4 & 2`) and the incoming
/// `v[1]` is positive, the 16-bit slope `0x80070980` is read; the side offset
/// becomes `face_scale * |v[1] * sin|` and the forward offset `v[1] * |cos|`.
/// The mirrored case uses `+0x10D4 & 1`, a negative `v[1]` and `0x80070920`.
/// Finally the `|v[0]|` magnitude is rotated by the incoming `angle` around
/// that offset.
///
/// # Original
/// - Ghidra: `FUN_800571C0` at `0x800571C0` (552 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800571c0_FUN_800571c0.c`
///
/// # Arguments
/// - `player`: gameplay actor; `+0x348` is the facing byte and `+0x10D4` the
///   state flags.
/// - `v`: address of three `f32` words `(side, forward, height)`.
/// - `angle`: 16-bit turn angle, already selected by the caller.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Calls `0x8006CD00` with the three-word result; `v` is not modified.
///
/// # Safety
/// `v` must be readable for three words and `player` must be a live actor with
/// the animation controller at `+0x1EC`.
///
/// # Confidence
/// medium - the branches, the clamps and the two helper identities are literal;
/// the GQR `psq_l` halfword conversions are reduced to `angle * 1/256`, the same
/// scale the sibling bodies read from `0x8042B8C0`.
pub unsafe fn fn_800571c0(player: usize, v: usize, angle: i16) {
    let facing = platform::read_u8(player + 0x348) as usize;
    let state = platform::read_u32(player + 0x10D4);
    let v0 = read_f32(v);
    let v1 = read_f32(v + 4);
    let v2 = read_f32(v + 8);

    let mut side = W87_ZERO_8042B878;
    let mut forward = v1;

    if state & 2 != 0 && W87_ZERO_8042B878 < v1 {
        let slope = platform::call2(
            W103_SLOPE_ALT_80070980,
            (player + 0x1EC) as u32,
            u32::from(platform::read_u8(player + 0x348)),
        ) as u16 as i16;
        if slope > 0 {
            let scaled = W103_ANGLE_SCALE_8042B8C0 * slope as f32;
            let sin = w103_sin_cos(W103_SIN_80237BD0, scaled);
            side = read_f32(W103_FACE_SCALE_8042B840 + facing * 4) * (v1 * sin).abs();
        }
        let scaled = W103_ANGLE_SCALE_8042B8C0 * slope as f32;
        let cos = w103_sin_cos(W103_COS_80237C40, scaled);
        forward = v1 * cos.abs();
    }

    if state & 1 != 0 && v1 < W87_ZERO_8042B878 {
        let slope = platform::call2(
            W103_SLOPE_80070920,
            (player + 0x1EC) as u32,
            u32::from(platform::read_u8(player + 0x348)),
        ) as u16 as i16;
        if slope < 0 {
            let scaled = W103_ANGLE_SCALE_8042B8C0 * slope as f32;
            let sin = w103_sin_cos(W103_SIN_80237BD0, scaled);
            side = read_f32(W103_FACE_SCALE_8042B840 + facing * 4) * (v1 * sin).abs();
        }
        let scaled = W103_ANGLE_SCALE_8042B8C0 * slope as f32;
        let cos = w103_sin_cos(W103_COS_80237C40, scaled);
        forward = v1 * cos.abs();
    }

    let magnitude = v0.abs();
    let scaled = W103_ANGLE_SCALE_8042B8C0 * angle as f32;
    let cos = w103_sin_cos(W103_COS_80237C40, scaled);
    let sin = w103_sin_cos(W103_SIN_80237BD0, scaled);
    let out = [side + magnitude * cos, forward + magnitude * sin, v2];
    platform::call2(
        W103_SET_VELOCITY_8006CD00,
        player as u32,
        out.as_ptr() as u32,
    );
}

// ---------------------------------------------------------------------------
// 0x800573F0 - signed speed cap and slope rotation
// ---------------------------------------------------------------------------

/// Caps the signed speed magnitude at `2.5`, then rotates it by the terrain
/// slope and the extra heading at `+0x1130`.
///
/// The rising/falling direction picks between `0x80070920` and `0x80070980`;
/// event `0x3B` selects the "on a slope" form, which forwards to
/// [`fn_800571c0`] with the extra heading, otherwise the vector is rotated by
/// the slope plus the `+0x1130` correction and published through `0x8006CD00`.
///
/// # Original
/// - Ghidra: `FUN_800573F0` at `0x800573F0` (600 bytes)
/// - Evidence: `work/ghidra/main-gb/export/800573f0_FUN_800573f0.c`
///
/// # Arguments
/// - `player`: gameplay actor; `+0x1130` is the extra heading halfword.
/// - `v`: address of three `f32` words; `v[0]` is clamped in place.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// May rewrite `v[0]` and calls `0x8006CD00` or [`fn_800571c0`].
///
/// # Safety
/// `v` must be readable and writable for three words and `player` must be a live
/// actor with the animation controller at `+0x1EC`.
///
/// # Confidence
/// medium - the cap, the event selection and the four rotations are literal;
/// the `+0x1130` field is inferred as an extra heading from how it is added to
/// the slope, and the GQR conversions are reduced to `angle * 1/256`.
pub unsafe fn fn_800573f0(player: usize, v: usize) {
    let state = platform::read_u32(player + 0x10D4);
    let speed = read_f32(v);
    if (speed > W87_ZERO_8042B878 && state & 0x40 != 0)
        || (speed < W87_ZERO_8042B878 && state & 0x20 != 0)
    {
        if W103_TWO_POINT_FIVE_8042B8CC < speed.abs() {
            // observed: the cap keeps the sign of the incoming value.
            let capped = if speed <= W87_ZERO_8042B878 {
                W103_NEG_TWO_POINT_FIVE_8042BA0C
            } else {
                W103_TWO_POINT_FIVE_8042B8CC
            };
            write_f32(v, capped);
        }
    }

    let falling = read_f32(v) < W87_ZERO_8042B878;
    let mut angle = platform::call2(
        W103_SLOPE_80070920,
        (player + 0x1EC) as u32,
        falling as u32,
    );
    if state & 2 != 0 {
        angle = platform::call2(
            W103_SLOPE_ALT_80070980,
            (player + 0x1EC) as u32,
            falling as u32,
        );
    }

    if fn_80056cf0(player, 0x3B) == 0 {
        let mut extra = 0i16;
        if fn_80056cf0(player, 0x13) != 0 {
            extra = platform::read_u16(player + 0x1130) as i16;
        }
        let slope_angle = angle as u16 as i16;
        let magnitude = read_f32(v).abs();
        let forward = read_f32(v + 4);

        let cos_slope = w103_sin_cos(
            W103_COS_80237C40,
            W103_ANGLE_SCALE_8042B8C0 * slope_angle as f32,
        );
        let sin_slope = w103_sin_cos(
            W103_SIN_80237BD0,
            W103_ANGLE_SCALE_8042B8C0 * slope_angle as f32,
        );
        let sin_extra = w103_sin_cos(
            W103_SIN_80237BD0,
            W103_ANGLE_SCALE_8042B8C0 * extra as f32,
        );
        let cos_extra = w103_sin_cos(
            W103_COS_80237C40,
            W103_ANGLE_SCALE_8042B8C0 * extra as f32,
        );

        let out = [
            magnitude * cos_slope - forward * sin_extra,
            magnitude * sin_slope + forward * cos_extra.abs(),
            read_f32(v + 8),
        ];
        platform::call2(
            W103_SET_VELOCITY_8006CD00,
            player as u32,
            out.as_ptr() as u32,
        );
    } else {
        // observed: the export copies `v` to a stack triple; the callee only
        // reads it, so the source address is passed directly.
        fn_800571c0(player, v, angle as u16 as i16);
    }
}

// ---------------------------------------------------------------------------
// 0x80058B20 - insert an effect into the first free slot
// ---------------------------------------------------------------------------

/// Inserts one effect into the owner's `+0x74` slot array, replacing the first
/// free entry.
///
/// The array holds `count = owner[+0x54]` entries of `{object, weight}` with a
/// stride of eight bytes. A free entry is `+0x74 == 0`; the routine stamps
/// `1.0` into its `+0x78` weight word, attaches the new object through
/// `0x8027B160(owner, slot, key, 0)`, and only when the attach stored a
/// non-zero object does it post the cue and the link.
///
/// # Original
/// - Ghidra: `FUN_80058B20` at `0x80058B20` (236 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80058b20_FUN_80058b20.c`
///
/// # Arguments
/// - `key`: word the effect is keyed by (also its `+0x9C` identity, see
///   [`fn_80058ee0`]).
/// - `owner`: holder of the count at `+0x54` and the slot array at `+0x74`.
/// - `cue`: sound/effect cue posted through `0x80196190`.
/// - `argument`: fourth word passed to `0x80197400`.
///
/// # Returns
/// Nothing; a full array is a silent no-op.
///
/// # Side effects
/// One `+0x78` weight write, one attach and at most one cue/link pair.
///
/// # Safety
/// `owner` must be live with a readable `+0x54` count and a writable slot array
/// of `count * 8` bytes at `+0x74`; the UI table at [`W18_UI_8042A488`] must be
/// readable.
///
/// # Confidence
/// medium - the search, the weight store and the three calls are literal; the
/// `+0x54`/`+0x74`/`+0x78` roles are inferred from the two inserters that share
/// them.
pub unsafe fn fn_80058b20(key: u32, owner: usize, cue: u32, argument: u32) {
    let count = platform::read_i32(owner + 0x54);
    let mut slot = 0usize;
    let mut index = 0i32;
    let mut remaining = count;
    while remaining != 0 {
        let base = owner + index as usize * 8;
        if platform::read_u32(base + 0x74) == 0 {
            write_f32(base + 0x78, W87_ONE_8042B874);
            slot = base + 0x74;
            break;
        }
        index += 1;
        remaining -= 1;
    }

    if slot != 0 {
        platform::call4(
            W103_SLOT_ATTACH_8027B160,
            owner as u32,
            slot as u32,
            key,
            0,
        );
        if platform::read_u32(slot) != 0 {
            platform::call3(
                W103_EFFECT_POST_80196190,
                platform::read_u32(W18_UI_8042A488),
                slot as u32,
                cue,
            );
            platform::call4(
                W103_EFFECT_LINK_80197400,
                owner as u32,
                slot as u32,
                key,
                argument,
            );
        }
    }
}

// ---------------------------------------------------------------------------
// 0x80058EE0 - reuse or insert an effect slot keyed by identity
// ---------------------------------------------------------------------------

/// Reuses the slot whose object already carries `key` at `+0x9C`, otherwise
/// takes the first free slot exactly like [`fn_80058b20`].
///
/// The difference from the sibling inserter is the attach entry point
/// `0x8027B1C0` (the "existing or create" variant) instead of `0x8027B160`;
/// the rest of the body - the search, the `1.0` weight, the cue (`0x80196190`)
/// and the link (`0x80197400`) - is identical.
///
/// # Original
/// - Ghidra: `FUN_80058EE0` at `0x80058EE0` (332 bytes)
/// - Evidence: `work/ghidra/main-gb/export/80058ee0_FUN_80058ee0.c`
///
/// # Arguments
/// Same as [`fn_80058b20`].
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Same as [`fn_80058b20`], with the extra read of the matched object's `+0x9C`.
///
/// # Safety
/// Same as [`fn_80058b20`]; every non-zero slot object must expose a readable
/// `+0x9C` word.
///
/// # Confidence
/// medium - both loops and the swapped attach call are literal; the `+0x9C`
/// identity word is inferred from the comparison alone.
pub unsafe fn fn_80058ee0(key: u32, owner: usize, cue: u32, argument: u32) {
    let count = platform::read_i32(owner + 0x54);
    let mut slot = 0usize;

    let mut index = 0i32;
    let mut entry = owner;
    let mut remaining = count;
    while remaining != 0 {
        let object = platform::read_u32(entry + 0x74);
        if object != 0 && key == platform::read_u32(object as usize + 0x9C) {
            slot = owner + index as usize * 8 + 0x74;
            break;
        }
        entry += 8;
        index += 1;
        remaining -= 1;
    }

    if slot == 0 {
        let mut index = 0i32;
        let mut entry = owner;
        let mut remaining = count;
        while remaining != 0 {
            if platform::read_u32(entry + 0x74) == 0 {
                let base = owner + index as usize * 8;
                write_f32(base + 0x78, W87_ONE_8042B874);
                slot = base + 0x74;
                break;
            }
            entry += 8;
            index += 1;
            remaining -= 1;
        }
    }

    if slot != 0 {
        platform::call4(
            W103_SLOT_ATTACH_8027B1C0,
            owner as u32,
            slot as u32,
            key,
            0,
        );
        if platform::read_u32(slot) != 0 {
            platform::call3(
                W103_EFFECT_POST_80196190,
                platform::read_u32(W18_UI_8042A488),
                slot as u32,
                cue,
            );
            platform::call4(
                W103_EFFECT_LINK_80197400,
                owner as u32,
                slot as u32,
                key,
                argument,
            );
        }
    }
}

