/// `1 << n` as the PowerPC `slw` computes it: zero for any count above `31`.
///
/// # Safety
/// Pure arithmetic; no memory is touched.
unsafe fn w211b_shift_one(bit: u8) -> u32 {
    if bit >= 32 {
        0
    } else {
        1u32 << bit
    }
}

