    loop {
        object = platform::call2(FN_80162D50_E, 0x019B, object as u32) as usize;
        if object == 0 {
            break;
        }
        if platform::read_u8(object + 0x0B) == 0 {
            let vtable = platform::read_u32(object + 0x60) as usize;
            let destroy = platform::read_u32(vtable + 0x5C) as usize;
            platform::call1(destroy, object as u32);
        }
    }

    let mut object = 0usize;
    loop {
        object = platform::call2(FN_80162DB0_B, 2, object as u32) as usize;
        if object == 0 {
            break;
        }
        if platform::read_u16(object + 0x08) != 0x019B
            && platform::read_u8(object + 0x0B) == 0
        {
            let vtable = platform::read_u32(object + 0x60) as usize;
            let destroy = platform::read_u32(vtable + 0x5C) as usize;
            platform::call1(destroy, object as u32);
        }
    }
