// ---------------------------------------------------------------------------
// 0x8006A760 - release a finished handle and report the idle state
// ---------------------------------------------------------------------------

/// Releases the open descriptor when its `+0x08` byte is set, then reports
/// whether the sound object still has an active source.
///
/// # Original
/// - Ghidra: `FUN_8006A760` at `0x8006_A760` (112 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8006a760_FUN_8006a760.c`
///
/// # Arguments
/// None.
///
/// # Returns
/// `1` when there is no open handle and `0x8019B9F0(sound)` is non-zero,
/// else `0`.
///
/// # Side effects
/// May call `0x8016B7E0(handle)` and zero [`DAT_80429D80_D`].
///
/// # Safety
/// A non-null handle must be readable at `+0x08`.
///
/// # Confidence
/// high - the two tests and the returned `0`/`1` are literal. Note that
/// `0x8019B9F0` is a constant `li r3,1; blr`, so the second test always
/// succeeds today; the call is still reproduced.
pub unsafe fn fn_8006a760() -> u32 {
    let handle = platform::read_u32(DAT_80429D80_D) as usize;
    if handle != 0 && platform::read_u8(handle + 0x08) != 0 {
        platform::call1(FN_8016B7E0_D, handle as u32);
        platform::write_u32(DAT_80429D80_D, 0);
    }

    let mut result = 0;
    if platform::read_u32(DAT_80429D80_D) == 0 {
        let sound = platform::read_u32(W74_SOUND_8042A4A8);
        if platform::call1(FN_8019B9F0_D, sound) != 0 {
            result = 1;
        }
    }
    result
}

// ---------------------------------------------------------------------------
// 0x8006A7D0 - set one request bit
// ---------------------------------------------------------------------------

/// Sets bit `index` of the request-mask byte.
///
/// # Original
/// - Ghidra: `FUN_8006A7D0` at `0x8006_A7D0` (28 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8006a7d0_FUN_8006a7d0.c`
///
/// # Arguments
/// - `index`: bit number. The PowerPC `slw` uses the low six bits of the
///   count and yields zero for counts `>= 32`, which the body reproduces; the
///   result is then masked to eight bits.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Read-modify-write of [`DAT_80429D84_D`].
///
/// # Safety
/// The mask byte must be writable.
///
/// # Confidence
/// high - `1 << index`, masked to a byte, ORed into the global.
pub unsafe fn fn_8006a7d0(index: u32) {
    let mask = platform::read_u8(DAT_80429D84_D);
    let shift = index & 0x3F;
    let bit = if shift < 32 { (1u32 << shift) as u8 } else { 0 };
    platform::write_u8(DAT_80429D84_D, mask | bit);
}

// ---------------------------------------------------------------------------
// 0x8006A7F0 - clear one request bit
// ---------------------------------------------------------------------------

/// Clears bit `index` of the request-mask byte.
///
/// # Original
/// - Ghidra: `FUN_8006A7F0` at `0x8006_A7F0` (32 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8006a7f0_FUN_8006a7f0.c`
///
/// # Arguments
/// - `index`: bit number, same `slw` low-six-bit shift as [`fn_8006a7d0`].
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// Read-modify-write of [`DAT_80429D84_D`].
///
/// # Safety
/// The mask byte must be writable.
///
/// # Confidence
/// high - the `nor`/`and` pair is exactly `mask & !(1 << index)`.
pub unsafe fn fn_8006a7f0(index: u32) {
    let mask = platform::read_u8(DAT_80429D84_D);
    let shift = index & 0x3F;
    let bit = if shift < 32 { (1u32 << shift) as u8 } else { 0 };
    platform::write_u8(DAT_80429D84_D, mask & !bit);
}

// ---------------------------------------------------------------------------
// 0x8006A830 - the per-frame request/pause state machine
// ---------------------------------------------------------------------------

/// One frame of the sound request machine: tracks the two-frame edge history,
/// accepts a new non-empty request when idle, enters the paused state on bit
/// `2`, and drops the request (or leaves the pause) when the transition
/// predicate reports completion.
///
/// The mask halves are:
///
/// * bit `1` (`0x2`) = pause request,
/// * bits `0`, `1` and `3` (`0xB`) = the request payload.
///
/// # Original
/// - Ghidra: `FUN_8006A830` at `0x8006_A830` (344 bytes)
/// - Evidence: `work/ghidra/main-gb/export/8006a830_FUN_8006a830.c`
///
/// # Arguments
/// - `flags`: incoming request word. Bit `2` is forced on when the game-mode
///   object's `+0x1D0` equals `2`, and the whole word is reduced to `0xB`.
///
/// # Returns
/// Nothing.
///
/// # Side effects
/// - may call `0x8019C670` / `0x8019C730` on the enable edge,
/// - may call `0x8019C7F0` / `0x8019C880` with the request mask,
/// - may call `0x800695F0` / `0x80069600` for the pause state,
/// - one `0x80195380(object, 0x7F, 1)` on entering the pause,
/// - updates the three mask bytes and the request words.
///
/// # Safety
/// The sound object, the mode object and the SDA bytes must be live.
///
/// # Confidence
/// medium - every branch is literal, but the flag semantics (request bit
/// layout and what `0x8006A9A0` checks) are inferred from this body.
pub unsafe fn fn_8006a830(mut flags: u32) {
    if platform::read_u8(DAT_80429D86_D) == 0 {
        if platform::read_u8(DAT_80429D85_D) != 0 {
            platform::call1(FN_8019C670_D, platform::read_u32(W74_SOUND_8042A4A8));
        }
    } else if platform::read_u8(DAT_80429D85_D) == 0 {
        platform::call1(FN_8019C730_D, platform::read_u32(W74_SOUND_8042A4A8));
    }

    platform::write_u8(DAT_80429D86_D, platform::read_u8(DAT_80429D85_D));
    platform::write_u8(DAT_80429D85_D, platform::read_u8(DAT_80429D84_D));

    let mode = call0_u32(FN_80109340_D) as usize;
    if platform::read_i32(mode + 0x1D0) == 2 {
        flags |= 8;
    }

    let request = flags & 0xB;
    if (flags & 2) == 0 {
        if platform::read_u32(DAT_80429D74_D) == 0 {
            platform::write_u32(DAT_80429D78_D, 0);
            if request != 0 {
                platform::write_u32(DAT_80429D74_D, request);
                platform::call1(FN_8019C7F0_D, platform::read_u32(W74_SOUND_8042A4A8));
            }
        }
    } else if platform::read_u8(DAT_80429D71_D) == 0 {
        platform::write_u8(DAT_80429D71_D, 1);
        platform::call0(FN_800695F0_D);
        platform::call3(
            FN_80195380_D,
            platform::read_u32(W92_EFFECT_TABLE_8042A488),
            0x7F,
            1,
        );
    }

    if platform::read_u8(DAT_80429D71_D) == 0 {
        if platform::read_u32(DAT_80429D74_D) != 0
            && call0_u32(FN_8006A9A0_D) != 0
            && request == 0
        {
            platform::write_u32(DAT_80429D74_D, 0);
            if platform::read_u32(DAT_80429D78_D) == 0 {
                platform::call1(FN_8019C880_D, platform::read_u32(W74_SOUND_8042A4A8));
            }
        }
    } else if call0_u32(FN_8006A9A0_D) != 0 && (flags & 2) == 0 {
        platform::write_u8(DAT_80429D71_D, 0);
        platform::call0(FN_80069600_D);
    }
}

