// ---------------------------------------------------------------------------
// 0x80040960 - table slot 0: start the fireball actor
// ---------------------------------------------------------------------------

/// Starts the fireball actor.
///
/// The body first runs its own `+0x114` and `+0x110` virtuals; either returning
/// zero sends the actor to the finish helper `0x80162510` and returns `0`.
/// Otherwise it resolves the owning player byte, applies the four class
/// virtuals `+0x114`, `+0x110`, `+0x118`, `+0x11C`, raises `0x80` in `+0x120`,
/// zeroes the three `+0xD0..+0xD8` floats, seeds `+0x36D = 4`, posts
/// `(+0x3D0, 2)` to the `+0x3EC` interface slot `+0x08`, runs the height query
/// into `+0x410`, snapshots the position into `+0x41C..+0x424` and finally
/// hands the `Move` descriptor `0x80353F0C` to the `+0x394` interface slot
/// `+0x18`.
///
/// # Original (untabled)
/// - Address: `0x80040960`, 360 B (`bclr 20,0` at `0x80040AC4`; the next
///   `functions.tsv` entry is `0x80040B00` after 8 bytes of padding)
/// - Table: slot 0 of `0x80323D40`, i.e. vtable `0x80323D38 + 0x08`
/// - Reach: `vcall(object, 0x08)` through the actor's `+0x60` vtable
/// - Not in `functions.tsv`; no Ghidra export
///
/// # Arguments
/// - `this`: the `0x560`-byte fireball actor.
///
/// # Returns
/// `1`, or `0` after the finish helper when either start virtual fails.
///
/// # Side effects
/// Calls `0x80162510`, `0x8008E770`, `0x80075270`; posts three virtuals and two
/// interface calls; writes `+0x349`, `+0x120`, `+0xD0..+0xD8`, `+0x36D`,
/// `+0x410` and `+0x41C..+0x424`.
///
/// # Safety
/// `this + 0x60`, `+0x394` and `+0x3EC` must hold live vtables and the current
/// WorldMap player at `0x8042A1C8` must be initialised.
///
/// # Confidence
/// high - every guard, virtual offset, field and the two state-descriptor
/// constants are literal transcriptions of the 90-instruction body.
pub unsafe fn fn_80040960(this: usize) -> u32 {
    if call_actor_slot1(this, 0x114) == 0 {
        platform::call1(E268_FN_80162510, this as u32);
        return 0;
    }
    if call_actor_slot1(this, 0x110) == 0 {
        platform::call1(E268_FN_80162510, this as u32);
        return 0;
    }

    // observed: `lbz` at `+0x120E`, `mulli 944`, `add` onto the table base.
    let player = platform::read_u32(E268_SDA_54B8_PLAYER) as usize;
    let table = platform::read_u32(E268_SDA_57E8_TABLE) as usize;
    let entry = table + platform::read_u8(player + 0x120E) as usize * 0x3B0;
    let owner_source = if platform::read_u32(entry + 0x2C) != 0 {
        entry
    } else {
        0
    };
    let owner = platform::call2(
        E268_FN_8008E770,
        owner_source as u32,
        (this + 0xAC) as u32,
    );
    platform::write_u8(this + 0x349, owner as u8);

    let _ = call_actor_slot1(this, 0x118);
    let _ = call_actor_slot1(this, 0x11C);

    platform::write_u32(this + 0x120, platform::read_u32(this + 0x120) | 0x80);
    let zero = read_f32(E268_ZERO_8042B730);
    write_f32(this + 0xD0, zero);
    write_f32(this + 0xD4, zero);
    write_f32(this + 0xD8, zero);
    platform::write_u8(this + 0x36D, 4);

    let _ = call_interface_slot2(this + 0x3EC, 0x08, (this + 0x3D0) as u32, 2);

    let height = e268_height_query(
        platform::read_u8(this + 0x38F) as u32,
        read_f32(this + 0xAC),
        read_f32(this + 0xB0),
        this + 0x418,
    );
    platform::write_u32(this + 0x410, height);
    write_f32(this + 0x41C, read_f32(this + 0xAC));
    write_f32(this + 0x420, read_f32(this + 0xB0));
    write_f32(this + 0x424, read_f32(this + 0xB4));

    let _ = call_interface_slot(this + 0x394, 0x18, E268_STATE_DESC_MOVE as u32);
    1
}

