#[inline]
unsafe fn d282_move_toward(value: usize, target: f32) -> u32 {
    let call: extern "C" fn(u32, f32, f32) -> u32 = core::mem::transmute(0x8015_F470usize);
    call(value as u32, target, D282_STEP_0_25)
}

